// loyalty-page - serve la pagina Area Membri Premia come application/liquid (richiesto da App Proxy).
// {% layout none %} = standalone senza tema; {% raw %} = markup verbatim (Liquid non lo parsa).
// BODY = pagina nuova (?v=2), BODY_V1 = pagina di prima (default, rollback). GENERATO da build.mjs: non modificare a mano.
const BODY = "{% layout none %}{% raw %}<!DOCTYPE html>\n<html lang=\"it\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>I tuoi punti Mimì · Amimì</title>\n<!--\n  Area Membri Amimi' - PRODUZIONE (dati REALI via App Proxy). Pagina nuova dal 2026-10-11 (call del 09-10):\n  solo punti Mimi' (niente livelli, niente timbri), sentiero a giro con la bandierina a scacchi al traguardo (scelta owner 12-10), elenco di tutti i codici\n  riscattati, memory con le foto vere delle borse, presenza agli eventi dal QR (?evento=CODICE).\n  Va servita SAME-ORIGIN su amimi.it, cosi' le fetch a /apps/premia/* portano il logged_in_customer_id firmato da\n  Shopify (nessun secondo login). Servita da un altro dominio NON funziona: il cookie di login e' su amimi.it.\n  Contratto edge loyalty-proxy v14: state | coccola | memory_win | rewards | redeem | profile | profile_save | track | deck | checkin.\n  Il costo e il valore del premio arrivano dal server (riga attiva di loyalty_rewards): qui nessun numero fisso.\n  La Mimi' e' src/mimi.webp: build.mjs la inserisce al posto del segnaposto nella costante MIMI (una sola occorrenza).\n  Tema: solo chiaro, per scelta (il negozio non ha un tema scuro e la Mimi' ha il bordo bianco da adesivo).\n  Forme: bottoni a pillola, card 20px, righe e campi 14px. Un solo colore d'accento: il rosso della Mimi'.\n-->\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,600;0,700;1,600&family=Work+Sans:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --red:#E10A0A; --red-deep:#A30008; --pink:#F9CBD0; --pink-soft:#FDECEE; --paper:#FFFBFB;\n    --ink:#2B1215; --muted:#7E5158; --line:#F3BFC6; --white:#FFFFFF;\n    --display:\"Cormorant Garamond\",Georgia,\"Times New Roman\",serif;\n    --body:\"Work Sans\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;\n    --ease:cubic-bezier(.3,.8,.3,1);\n    --chk:conic-gradient(var(--red) 90deg,var(--white) 90deg 180deg,var(--red) 180deg 270deg,var(--white) 270deg);\n    color-scheme:light;\n  }\n  *{box-sizing:border-box;margin:0;padding:0}\n  html{-webkit-text-size-adjust:100%}\n  body{background:var(--pink-soft);font-family:var(--body);font-size:15px;line-height:1.45;color:var(--ink);max-width:480px;margin:0 auto;padding:18px 16px 56px;min-height:100dvh;position:relative;overflow-x:hidden}\n  button{font:inherit;color:inherit}\n  a{color:var(--red-deep)}\n  :focus-visible{outline:2.5px solid var(--red-deep);outline-offset:2px}\n  .hidden{display:none!important}\n  .tap{cursor:pointer;-webkit-tap-highlight-color:transparent;user-select:none}\n  .tap:active{transform:scale(.98)}\n  .logo{display:block;width:max-content;margin:0 auto;font-family:var(--display);font-style:italic;font-weight:600;font-size:26px;line-height:1.2;color:var(--red-deep);text-decoration:none;letter-spacing:.5px}\n  h2{font-family:var(--display);font-weight:700;font-size:25px;line-height:1.1;margin-bottom:12px}\n  main{display:flex;flex-direction:column;gap:28px;margin-top:14px}\n  .btn{display:inline-block;background:var(--red);color:var(--white);font-size:15px;font-weight:700;padding:14px 26px;border-radius:99px;border:none;cursor:pointer;text-decoration:none}\n\n  /* caricamento: la sagoma della pagina */\n  .skel{display:flex;flex-direction:column;gap:16px;margin-top:22px}\n  .skel i{display:block;border-radius:20px;background:linear-gradient(90deg,var(--pink) 25%,var(--paper) 37%,var(--pink) 63%);background-size:400% 100%;animation:shimmer 1.5s ease infinite}\n  @keyframes shimmer{0%{background-position:100% 50%}100%{background-position:0 50%}}\n  .sk-hero{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:8px}   /* Mimi' c'e' gia' mentre si carica, dove sara' nel saluto */\n  .sk-hero img{display:block;width:150px;height:auto;animation:floaty 3.6s ease-in-out infinite}\n\n  /* stati: accesso richiesto, programma spento, errore */\n  .gate{text-align:center;padding:36px 12px;display:flex;flex-direction:column;align-items:center;gap:12px}\n  .gate img{width:164px;height:auto;animation:floaty 3.6s ease-in-out infinite}\n  .gate h1{font-family:var(--display);font-size:32px;font-weight:700;line-height:1.05;text-wrap:balance}\n  .gate p{font-size:15px;color:var(--muted);max-width:34ch}\n\n  /* saluto + Mimi': e' lei che parla (il fumetto) e si lascia coccolare con un tocco (owner 12-10: \"piu' presente\") */\n  .hero{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:8px}\n  .hello{font-family:var(--display);font-size:44px;font-weight:700;line-height:.98}\n  .says{position:relative;display:inline-block;margin-top:12px;background:var(--white);border:1.5px solid var(--line);border-radius:16px;padding:10px 13px;font-size:14px;line-height:1.35;max-width:23ch;min-height:calc(2.7em + 23px)}\n  .says::after{content:\"\";position:absolute;right:-7px;top:50%;width:12px;height:12px;margin-top:-6px;background:var(--white);border:solid var(--line);border-width:1.5px 1.5px 0 0;transform:rotate(45deg)}\n  .says.new{animation:says .35s var(--ease)}\n  @keyframes says{0%{opacity:0;transform:translateX(-6px) scale(.96)}100%{opacity:1;transform:none}}\n  .hero-mimi{position:relative;display:block;width:150px;background:none;border:none;padding:0;border-radius:24px;cursor:pointer}\n  .hero-mimi img{display:block;width:100%;height:auto;animation:floaty 3.6s ease-in-out infinite;filter:drop-shadow(0 6px 6px rgba(163,0,8,.16))}\n  .hero-mimi.squee img{animation:squee .7s ease}\n  @keyframes floaty{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}\n  @keyframes squee{0%{transform:scale(1)}30%{transform:scale(1.09) rotate(-3deg)}60%{transform:scale(.97) rotate(2deg)}100%{transform:scale(1)}}\n  .spark{position:absolute;width:16px;height:16px;background:var(--red);clip-path:polygon(50% 0,62% 38%,100% 50%,62% 62%,50% 100%,38% 62%,0 50%,38% 38%);pointer-events:none;animation:rise 1.2s ease-out forwards;z-index:5}\n  @keyframes rise{0%{opacity:0;transform:translateY(6px) scale(.6)}20%{opacity:1}100%{opacity:0;transform:translateY(-58px) scale(1.2)}}\n  .confetti{position:fixed;width:10px;height:10px;z-index:95;pointer-events:none;animation:fall linear forwards}\n  @keyframes fall{0%{opacity:1;transform:translateY(-10px) rotate(0)}100%{opacity:.9;transform:translateY(100vh) rotate(540deg)}}\n\n  /* avvisi: evento dal QR, compleanno */\n  .note{display:flex;align-items:center;gap:12px;background:var(--white);border:1.5px solid var(--red);border-radius:20px;padding:14px 16px;font-size:14px}\n  .note b{display:block;font-family:var(--display);font-size:21px;font-weight:700;line-height:1.1;color:var(--red-deep)}\n  .note .txt{flex:1;min-width:0}\n  .note .mini{flex:none;background:var(--red);color:var(--white);border:none;border-radius:99px;font-size:14px;font-weight:700;padding:0 16px;min-height:44px;cursor:pointer}\n  .percorso:focus{outline:none}\n\n  /* bandierina a scacchi */\n  .flag{position:relative;display:block;width:22px;height:30px;flex:none}\n  .flag::before{content:\"\";position:absolute;left:2px;top:0;bottom:0;width:2px;border-radius:2px;background:var(--red-deep)}\n  .flag i{position:absolute;left:4px;top:1px;width:17px;height:13px;border:1px solid var(--red-deep);transform-origin:left center;opacity:.32;background:var(--chk) 0 0/8px 8px}\n  .flag.on i{opacity:1;animation:wave 1.7s ease-in-out infinite}\n  @keyframes wave{0%,100%{transform:skewY(0)}50%{transform:skewY(-9deg)}}\n\n  /* punti e percorso */\n  .percorso{background:var(--white);border:1.5px solid var(--line);border-radius:20px;padding:22px 16px 18px;display:flex;flex-direction:column;gap:12px}\n  .pts{display:flex;align-items:baseline;justify-content:center;gap:10px}\n  .pts .n{font-family:var(--display);font-size:68px;font-weight:700;color:var(--red);line-height:.85;font-variant-numeric:tabular-nums}\n  .pts .l{font-size:12px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}\n  /* il sentiero: un giro vale un premio. Mimi' lo percorre, le tappe sono a un quarto, meta' e tre quarti, la bandierina grande e' il traguardo */\n  .road{position:relative;width:100%;max-width:340px;margin:0 auto;aspect-ratio:320/260}\n  .road svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}\n  .road .r-bg{fill:none;stroke:var(--pink);stroke-width:13;stroke-linecap:round}\n  .road .r-fg{fill:none;stroke:var(--red);stroke-width:13;stroke-linecap:round}\n  .road .r-dash{fill:none;stroke:var(--white);stroke-width:2;stroke-dasharray:5 7;stroke-linecap:round}\n  .road .stop circle{fill:var(--white);stroke:var(--line);stroke-width:2.5}\n  .road .stop.on circle{fill:var(--red);stroke:var(--red-deep)}\n  .road .lbl{font-family:var(--body);font-size:12px;font-weight:600;fill:var(--muted);paint-order:stroke;stroke:var(--white);stroke-width:4px;stroke-linejoin:round;font-variant-numeric:tabular-nums}\n  .road .lbl.on{fill:var(--red-deep)}\n  .road .goal{position:absolute;width:30px;height:40px;transform:translate(-3px,-100%);z-index:2}\n  .road .goal i{width:24px;height:18px;background-size:12px 12px}\n  .road .goal.pop{animation:pop .55s var(--ease)}\n  @keyframes pop{0%{transform:translate(-3px,-100%) scale(1)}40%{transform:translate(-3px,-100%) scale(1.4) rotate(-10deg)}100%{transform:translate(-3px,-100%) scale(1)}}\n  .road .runner{position:absolute;width:19%;transform:translate(-50%,-78%);z-index:3}\n  .road .runner img{display:block;width:100%;height:auto;filter:drop-shadow(0 3px 3px rgba(163,0,8,.18));animation:floaty 3.6s ease-in-out infinite}\n  .road .runner.go img{animation:step .32s ease-in-out infinite}\n  @keyframes step{0%,100%{transform:translateY(0) rotate(-4deg)}50%{transform:translateY(-6px) rotate(4deg)}}\n  .pronti{display:flex;align-items:center;justify-content:center;gap:2px;font-size:13px;color:var(--muted)}\n  .pronti .flag{width:20px;height:26px}\n  .pronti em{font-style:normal;font-weight:600;color:var(--red-deep);margin-left:6px}\n  .status{text-align:center;font-size:15px}\n  .status b{color:var(--red-deep)}\n  .rbtn{background:var(--red);color:var(--white);border:none;border-radius:99px;font-size:15px;font-weight:700;padding:15px 18px;cursor:pointer;width:100%;transition:transform .12s,opacity .2s}\n  .rbtn[disabled]{background:var(--pink);color:var(--muted);cursor:default}\n  .bonus2{font-size:13px;color:var(--muted);text-align:center;border-top:1.5px dashed var(--line);padding-top:12px}\n  .bonus2 b{color:var(--red-deep)}\n\n  /* i tuoi codici */\n  .codici{list-style:none;display:grid;gap:8px}\n  .cod{display:flex;align-items:center;gap:12px;background:var(--white);border:1.5px solid var(--line);border-radius:14px;padding:13px 14px}\n  .cod-main{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}\n  .cod-c{font-weight:700;font-size:16px;letter-spacing:.04em;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}\n  .cod-m{font-size:13px;color:var(--muted)}\n  .cod.used{background:transparent}\n  .cod.used .cod-c{color:var(--muted);text-decoration:line-through}\n  .cp{flex:none;background:var(--red);color:var(--white);border:none;border-radius:99px;font-size:14px;font-weight:700;padding:0 16px;min-width:80px;min-height:44px;cursor:pointer}\n  .chip{flex:none;font-size:12px;font-weight:600;color:var(--muted);border:1.5px solid var(--line);border-radius:99px;padding:6px 11px}\n  .link{background:none;border:none;color:var(--red-deep);font-size:14px;font-weight:600;text-decoration:underline;cursor:pointer;padding:0 4px;min-height:44px;margin-top:4px}\n\n  /* ogni giorno */\n  .acts{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n  .act{border-radius:16px;padding:16px 10px;text-align:center;font-size:15px;font-weight:700;border:1.5px solid var(--red);background:var(--white);color:var(--red-deep);min-height:72px;transition:transform .12s}\n  .act small{display:block;font-weight:500;font-size:12.5px;margin-top:3px;color:var(--muted)}\n  .act.main{background:var(--red);color:var(--white)}\n  .act.main small{color:var(--white)}\n  .act.done{background:var(--pink);border-color:var(--pink);color:var(--muted);cursor:default}\n  .act .ico{display:block;height:44px;width:auto;margin:0 auto 7px}\n  .act img.ico{width:44px;object-fit:contain;padding:5px;background:var(--white);border-radius:50%}   /* Mimi' su un tondo bianco: si legge anche sul bottone rosso */\n  .act .ico.carta{width:33px;border-radius:6px;border:1.5px solid var(--red-deep);background:var(--chk) 0 0/50% 37.5%}\n  .act.done .ico{opacity:.5}\n\n  /* come prendi i punti */\n  .regole{list-style:none;display:grid;gap:11px}\n  .regole li{display:flex;justify-content:space-between;align-items:baseline;gap:14px;font-size:15px}\n  .regole b{color:var(--red-deep);font-weight:600;text-align:right;white-space:nowrap}\n  .fine{font-size:13px;color:var(--muted);margin-top:14px}\n  .fine b{color:var(--ink);font-weight:600}\n\n  /* le tue borse */\n  .ward{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}\n  .witem{background:var(--white);border-radius:14px;padding:7px;border:1.5px solid var(--line);min-width:0}\n  .witem img,.witem .noimg{display:block;width:100%;aspect-ratio:3/4;object-fit:cover;border-radius:9px;background:var(--pink)}\n  .witem figcaption{font-size:11.5px;color:var(--muted);margin-top:6px;line-height:1.25;text-align:center;overflow-wrap:anywhere}\n  .empty{background:var(--white);border:1.5px dashed var(--line);border-radius:14px;padding:18px;text-align:center;font-size:14px;color:var(--muted)}\n  .empty.mimi{display:flex;align-items:center;gap:12px;text-align:left}\n  .empty.mimi img{width:60px;height:auto;flex:none}\n\n  /* saluto finale di Mimi' */\n  .ciao{display:flex;align-items:center;gap:14px;border-top:1.5px dashed var(--line);padding-top:22px}\n  .ciao img{width:76px;height:auto;flex:none}\n  .ciao p{font-size:14px;color:var(--muted);min-width:0}\n  .ciao b{display:block;font-family:var(--display);font-size:23px;font-weight:700;line-height:1.1;color:var(--ink);margin-bottom:3px}\n\n  /* profilo (compleanno, materiale): solo a flag acceso */\n  .prof{background:var(--white);border:1.5px solid var(--line);border-radius:20px;padding:18px 16px}\n  .prof .row{display:flex;gap:8px;margin-top:10px}\n  .prof label{display:block;font-size:12px;font-weight:600;color:var(--muted);margin-bottom:4px}\n  .prof select{width:100%;border:1.5px solid var(--line);border-radius:14px;background:var(--white);padding:11px 10px;font:inherit;font-size:16px;color:var(--ink)}\n  .prof select[disabled]{background:var(--pink-soft);color:var(--muted)}\n  .prof .chk{display:flex;gap:9px;align-items:flex-start;margin-top:12px;font-size:13px;color:var(--muted);line-height:1.4}\n  .prof .chk input{margin-top:2px;accent-color:var(--red);width:18px;height:18px;flex:none}\n  .prof .chk label{font-size:13px;font-weight:400;margin:0}\n  .prof .sbtn{width:100%;margin-top:14px;background:var(--red);color:var(--white);border:none;border-radius:99px;font-size:15px;font-weight:700;padding:14px;cursor:pointer}\n  .prof .sbtn[disabled]{opacity:.55;cursor:default}\n  .prof .sum{font-size:15px;line-height:1.7}\n  .prof .sum b{color:var(--red-deep)}\n  .prof .got{display:inline-block;font-size:13px;font-weight:600;color:var(--red-deep);margin-top:8px}\n  .prof .pnote{font-size:13px;color:var(--muted);margin-top:8px;line-height:1.4}\n  .prof .pnote b{color:var(--ink)}\n\n  #toast{position:fixed;left:50%;bottom:26px;transform:translateX(-50%) translateY(20px);background:var(--ink);color:var(--white);font-size:14px;padding:11px 18px;border-radius:99px;opacity:0;pointer-events:none;transition:opacity .3s,transform .3s;z-index:96;max-width:88%;text-align:center}\n  #toast.on{opacity:.96;transform:translateX(-50%) translateY(0)}\n\n  /* finestre: memory e premio */\n  .modal{position:fixed;inset:0;background:rgba(43,18,21,.6);display:flex;z-index:90;opacity:0;visibility:hidden;transition:opacity .25s,visibility 0s .25s;padding:84px 20px 20px;overflow-y:auto}   /* in alto c'e' il posto per Mimi' che sporge; su uno schermo basso la finestra parte dall'alto e si scorre */\n  .modal.on{opacity:1;visibility:visible;transition:opacity .25s}\n  .sheet{position:relative;margin:auto;background:var(--paper);border-radius:20px;padding:24px 20px 18px;width:100%;max-width:360px;text-align:center;box-shadow:0 20px 50px rgba(43,18,21,.35)}\n  /* Mimi' nelle finestre: porta lei il premio (in cima, a cavallo del bordo) e guarda la partita dal bordo del memory */\n  .sheet-mimi{width:96px;margin:-84px auto 2px}\n  .sheet-peek{position:absolute;right:14px;top:0;width:68px;transform:translateY(-78%)}\n  .sheet-mimi img,.sheet-peek img{display:block;width:100%;height:auto;filter:drop-shadow(0 4px 4px rgba(163,0,8,.18))}\n  .modal.on .sheet-mimi img{animation:hop .7s var(--ease) .12s both}\n  .sheet-peek.hop img{animation:hop .6s var(--ease)}\n  @keyframes hop{0%,100%{transform:translateY(0)}35%{transform:translateY(-16px) rotate(-5deg)}70%{transform:translateY(0) rotate(3deg)}}\n  .sheet h2{font-size:29px;margin-bottom:4px}\n  .sheet p{font-size:14px;color:var(--muted)}\n  .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin:16px 0 10px}\n  .card{position:relative;aspect-ratio:3/4;border:none;padding:0;background:none;border-radius:12px;cursor:pointer;perspective:700px}\n  .card[disabled]{cursor:default}\n  .card .in{position:absolute;inset:0;border-radius:12px;transition:transform .38s var(--ease);transform-style:preserve-3d}\n  .card.up .in,.card.done .in{transform:rotateY(180deg)}\n  .card .back,.card .front{position:absolute;inset:0;border-radius:12px;overflow:hidden;backface-visibility:hidden;-webkit-backface-visibility:hidden}\n  .card .back{background:var(--chk) 0 0/50% 37.5%;border:1.5px solid var(--red-deep);display:flex;align-items:center;justify-content:center}\n  .card .back img{width:46%;height:auto;background:var(--white);border-radius:50%;padding:5px;box-shadow:0 0 0 1.5px var(--red-deep)}\n  .card .front{transform:rotateY(180deg);background:var(--white);border:1.5px solid var(--line);display:flex;align-items:center;justify-content:center}\n  .card .front img{display:block;width:100%;height:100%;object-fit:cover}\n  .card .front.glyph img{width:70%;height:auto;object-fit:contain}\n  .card .front.glyph.chk{background:var(--chk) 0 0/50% 37.5%}\n  .card .front.glyph.word{font-family:var(--display);font-style:italic;font-weight:600;font-size:22px;color:var(--red-deep)}\n  .card.done .front{border-color:var(--red);box-shadow:inset 0 0 0 2px var(--red)}\n  .card.loading .back{opacity:.5}\n  .prizebig{font-family:var(--display);font-size:60px;font-weight:700;color:var(--red);line-height:1;margin:6px 0}\n  .codechip{display:flex;align-items:center;gap:8px;background:var(--white);border:1.5px solid var(--line);border-radius:14px;padding:10px 10px 10px 14px;margin:12px 0 4px;text-align:left}\n  .codechip .c{flex:1;min-width:0;font-weight:700;font-size:17px;letter-spacing:.04em;overflow-wrap:anywhere}\n  .sheet .btn{width:100%;margin-top:14px}\n  .btnghost{background:none;border:none;color:var(--muted);font-size:14px;font-weight:600;margin-top:4px;padding:0 12px;min-height:44px;cursor:pointer;text-decoration:underline}\n\n  @media (min-width:360px){ .hero-mimi,.sk-hero img{width:168px} }\n  @media (min-width:420px){ .hero-mimi,.sk-hero img{width:186px} .hello{font-size:50px} }\n  @media (prefers-reduced-motion:reduce){\n    *,*::before,*::after{animation:none!important;transition:none!important}\n  }\n</style>\n</head>\n<body>\n  <a class=\"logo\" href=\"/\" aria-label=\"Amimì, torna al sito\">amìmì</a>\n\n  <!-- stato: caricamento -->\n  <div id=\"loading\" class=\"skel\" role=\"status\" aria-label=\"Carico i tuoi punti Mimì\">\n    <div class=\"sk-hero\"><i style=\"height:118px\"></i><img data-mimi alt=\"\"></div><i style=\"height:262px\"></i><i style=\"height:76px\"></i>\n  </div>\n\n  <!-- stato: accesso richiesto / programma spento / errore -->\n  <div id=\"gate\" class=\"gate hidden\">\n    <img data-mimi alt=\"\">\n    <h1 id=\"gateTitle\"></h1>\n    <p id=\"gateMsg\"></p>\n    <a id=\"gateBtn\" class=\"btn\" href=\"/account\">Accedi</a>\n    <button id=\"gateRetry\" class=\"btn hidden\" type=\"button\">Riprova</button>\n  </div>\n\n  <!-- area membri -->\n  <main id=\"app\" class=\"hidden\">\n    <div class=\"hero\">\n      <div>\n        <h1 class=\"hello\">Ciao,<br>amica</h1>\n        <div class=\"says\"><p id=\"mood\"></p></div>\n      </div>\n      <button class=\"hero-mimi tap\" id=\"mimi\" type=\"button\" aria-describedby=\"mood\"><img data-mimi alt=\"\"></button>\n    </div>\n\n    <div id=\"evento\" class=\"note hidden\" role=\"status\"></div>\n    <div id=\"bday\" class=\"note hidden\"></div>\n\n    <section class=\"percorso\" id=\"redeem\" aria-label=\"I tuoi punti Mimì\" tabindex=\"-1\">\n      <div class=\"pts\"><span class=\"n\" id=\"pts\">0</span><span class=\"l\">punti Mimì</span></div>\n      <div class=\"road hidden\" id=\"walk\" role=\"img\">\n        <svg viewBox=\"0 0 320 260\" aria-hidden=\"true\">\n          <path class=\"r-bg\" d=\"M28 232 C 110 246, 250 244, 284 204 C 308 172, 236 152, 160 156 C 96 160, 34 148, 44 108 C 52 74, 130 68, 190 74 C 236 78, 266 66, 286 46\"/>\n          <path class=\"r-fg\" pathLength=\"100\" stroke-dasharray=\"0 100\" d=\"M28 232 C 110 246, 250 244, 284 204 C 308 172, 236 152, 160 156 C 96 160, 34 148, 44 108 C 52 74, 130 68, 190 74 C 236 78, 266 66, 286 46\"/>\n          <path class=\"r-dash\" d=\"M28 232 C 110 246, 250 244, 284 204 C 308 172, 236 152, 160 156 C 96 160, 34 148, 44 108 C 52 74, 130 68, 190 74 C 236 78, 266 66, 286 46\"/>\n          <g id=\"roadMarks\"></g>\n        </svg>\n        <span class=\"flag goal\"><i></i></span>\n        <div class=\"runner\"><img data-mimi alt=\"\"></div>\n      </div>\n      <div class=\"pronti hidden\" id=\"pronti\"></div>\n      <p class=\"status\" id=\"pathStatus\"></p>\n      <div id=\"redeemBox\"></div>\n      <div id=\"bonus2\" class=\"bonus2 hidden\"></div>\n    </section>\n\n    <section id=\"codiciSec\" class=\"hidden\">\n      <h2>I tuoi codici</h2>\n      <ul id=\"codici\" class=\"codici\"></ul>\n      <button id=\"codiciTutti\" class=\"link hidden\" type=\"button\"></button>\n    </section>\n\n    <section>\n      <h2>Ogni giorno</h2>\n      <div class=\"acts\">\n        <button class=\"act main tap\" id=\"btnCoccola\" type=\"button\"></button>\n        <button class=\"act tap\" id=\"btnGame\" type=\"button\"></button>\n      </div>\n    </section>\n\n    <section id=\"profSec\" class=\"hidden\">\n      <h2>Il tuo profilo</h2>\n      <div id=\"profilo\" class=\"prof\"></div>\n    </section>\n\n    <section id=\"regoleSec\">\n      <h2>Come prendi i punti</h2>\n      <ul class=\"regole\" id=\"regole\"></ul>\n      <p class=\"fine\" id=\"regoleNota\"></p>\n    </section>\n\n    <section>\n      <h2>Le tue borse</h2>\n      <div id=\"ward\"></div>\n    </section>\n\n    <footer class=\"ciao\">\n      <img data-mimi alt=\"\">\n      <p><b>A presto, amica</b>Torna a trovarmi domani: ti aspetto con la coccola e il memory. <a href=\"/\" id=\"shopFine\">Vai allo shop</a></p>\n    </footer>\n  </main>\n\n  <!-- memory -->\n  <div class=\"modal\" id=\"gameModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"gameTitle\" aria-hidden=\"true\"><div class=\"sheet\">\n    <div class=\"sheet-peek\" id=\"gameMimi\"><img data-mimi alt=\"\"></div>\n    <h2 id=\"gameTitle\">Trova le coppie</h2>\n    <p id=\"gameMsg\">Abbina le borse uguali e vinci i punti di oggi.</p>\n    <div class=\"grid\" id=\"grid\"></div>\n    <button class=\"btnghost\" id=\"gameClose\" type=\"button\">Chiudi</button>\n  </div></div>\n\n  <!-- premio -->\n  <div class=\"modal\" id=\"rewardModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"rewardTitle\" aria-hidden=\"true\"><div class=\"sheet\">\n    <div class=\"sheet-mimi\"><img data-mimi alt=\"\"></div>\n    <h2 id=\"rewardTitle\">Complimenti!</h2>\n    <div class=\"prizebig\" id=\"rewardPrize\"></div>\n    <p id=\"rewardMsg\"></p>\n    <div id=\"rewardCode\"></div>\n    <button class=\"btn\" id=\"rewardOk\" type=\"button\">Continua</button>\n  </div></div>\n\n  <div id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n<script>\n(function(){\n  \"use strict\";\n\n  // === CONFIG (i punti veri, il costo e il valore del premio arrivano dall'edge) ===\n  const CONFIG = {\n    codiciVisibili: 3,     // codici mostrati prima di \"Mostra tutti\"\n    coppie: 3,             // coppie del memory\n    eventoOre: 12,         // per quante ore il codice di un QR resta in attesa dell'accesso\n    materiali: ['cavallino','cocco','vernice','pelle liscia','cotone','nessuna preferenza'],   // lista chiusa, uguale al check a DB (migr 0141)\n    mesi: ['gennaio','febbraio','marzo','aprile','maggio','giugno','luglio','agosto','settembre','ottobre','novembre','dicembre'],\n  };\n  const PROXY = '/apps/premia';         // same-origin su amimi.it\n  const MIMI = 'data:image/webp;base64,';\n  const ICO_MIMI = '<img class=\"ico\" alt=\"\" src=\"'+MIMI+'\">', ICO_CARTA = '<span class=\"ico carta\"></span>';   // le due azioni del giorno: Mimi' e la carta a scacchi del memory\n  const el = id => document.getElementById(id);\n  const esc = s => String(s ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));   // tutto cio' che entra in innerHTML passa da qui (audit T7)\n  const reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);\n  let S = null;                          // stato reale dall'edge\n  let tuttiICodici = false;\n  document.querySelectorAll('[data-mimi]').forEach(i => { i.src = MIMI; });\n\n  // === API reale (rispecchia loyalty-proxy) ===\n  async function api(action, opts){\n    const o = opts || {};\n    const url = PROXY + '/' + action;\n    const init = { method: o.method || 'GET', headers: { 'Content-Type':'application/json' }, credentials:'include' };\n    if (o.body) init.body = JSON.stringify(o.body);\n    let r;\n    try { r = await fetch(url, init); } catch(e) { return { status:0, data:{ error:'network' } }; }   // offline o rete: gli handler mostrano \"Riprova\" (audit T30)\n    let data = null; try { data = await r.json(); } catch(e){}\n    if(!data || typeof data!=='object') data = { error:'bad_response' };                              // corpo non JSON (502 del gateway, pagina HTML): mai scambiarlo per una risposta buona\n    else if(!r.ok && !data.error && !data.reason && !data.state) data.error = 'http_'+r.status;         // errore senza un motivo dichiarato\n    return { status:r.status, data };\n  }\n\n  // === tracciamento (loyalty-proxy v13, migr 0146 e 0150): apertura, card viste, tap. Solo nome dell'evento e dell'elemento,\n  // in lotti (max 20, invio dopo 4 s o quando la pagina va in background), max 60 per caricamento pagina. A flag\n  // loyalty_track_enabled spento il server risponde {state:'off'} e la pagina smette di mandare. Mai bloccante, mai un toast.\n  const T = { q:[], sent:0, off:false, seen:{}, timer:null, started:false, MAX:60 };\n  function track(e, name){\n    if(T.off || T.sent + T.q.length >= T.MAX) return;\n    if(e==='view'){ if(T.seen[name]) return; T.seen[name]=1; }\n    T.q.push(name ? { e:e, el:name } : { e:e });\n    if(!T.timer) T.timer=setTimeout(flush, 4000);\n  }\n  function flush(){\n    clearTimeout(T.timer); T.timer=null;\n    if(T.off || !T.q.length) return;\n    const batch=T.q.splice(0,20); T.sent+=batch.length;\n    fetch(PROXY+'/track', { method:'POST', headers:{ 'Content-Type':'application/json' }, credentials:'include', keepalive:true, body:JSON.stringify({ events:batch }) })\n      .then(r=>r.json()).then(d=>{ if(d && d.state==='off'){ T.off=true; T.q=[]; } else if(T.q.length) flush(); }).catch(()=>{});\n  }\n  document.addEventListener('visibilitychange', ()=>{ if(document.visibilityState==='hidden') flush(); });\n  // \"vista\" = meta' della card a schermo, oppure almeno 40% dello schermo occupato (una card piu' alta di due schermi, es. un guardaroba lungo, non arriva mai al 50%)\n  const io = ('IntersectionObserver' in window) ? new IntersectionObserver(es=>{ es.forEach(x=>{ if(x.isIntersecting && x.target.dataset.trk && (x.intersectionRatio>=0.5 || x.intersectionRect.height>=window.innerHeight*0.4)) track('view', x.target.dataset.trk); }); }, { threshold:[0,0.25,0.5] }) : null;\n  function watch(id, name){ const n=el(id); if(!n || !io) return; if(name) n.dataset.trk=name; io.observe(n); }\n  function trackStart(){\n    if(T.started) return; T.started=true;\n    track('page_open');\n    watch('redeem'); watch('codiciSec','codici'); watch('profSec','profilo'); watch('mimi','mimi'); watch('regoleSec','regole'); watch('ward','guardaroba'); watch('bonus2','bonus2'); watch('bday','bday'); watch('evento','evento');\n  }\n\n  // === piccoli effetti ===\n  function toast(m){ const t=el('toast'); t.textContent=m; t.classList.add('on'); clearTimeout(t._t); t._t=setTimeout(()=>t.classList.remove('on'),2400); }\n  function sparkles(host,n){ if(reduced) return; n=n||6; for(let k=0;k<n;k++){ (function(k){ setTimeout(()=>{ const h=document.createElement('i'); h.className='spark'; const z=10+Math.random()*10; h.style.width=h.style.height=z+'px'; h.style.left=(8+Math.random()*78)+'%'; h.style.top=(18+Math.random()*46)+'%'; host.appendChild(h); setTimeout(()=>h.remove(),1300); }, k*110); })(k);} }\n  function squee(){ const m=el('mimi'); m.classList.remove('squee'); void m.offsetWidth; m.classList.add('squee'); setTimeout(()=>m.classList.remove('squee'),750); }\n  function confetti(){ if(reduced) return; const cols=['#E10A0A','#F9CBD0','#FFFFFF','#A30008','#F3BFC6']; for(let i=0;i<64;i++){ const c=document.createElement('div'); c.className='confetti'; c.style.left=Math.random()*100+'%'; c.style.top='-10px'; c.style.background=cols[i%cols.length]; c.style.animationDuration=(1.6+Math.random()*1.3)+'s'; document.body.appendChild(c); setTimeout(()=>c.remove(),3200);} }\n  // il conteggio e' solo estetica: il valore finale arriva comunque dopo 900 ms, anche se la scheda e' in secondo piano e i fotogrammi sono fermi\n  function countUp(node,to){ const from=Number(node.textContent)||0; clearTimeout(node._end); node._to=to; if(from===to || reduced){node.textContent=to;return;} const t0=performance.now(); (function step(t){ if(node._to!==to) return; const k=Math.min(1,(t-t0)/700); node.textContent=Math.round(from+(to-from)*(1-Math.pow(1-k,3))); if(k<1) requestAnimationFrame(step); })(performance.now()); node._end=setTimeout(()=>{ if(node._to===to) node.textContent=to; },900); }\n  function itDate(iso){ const m=/^(\\d{4})-(\\d{2})-(\\d{2})/.exec(String(iso||'')); return m ? (m[3]+'/'+m[2]+'/'+m[1]) : ''; }\n  function thumb(u, w){ u=String(u||''); return u.indexOf('https://cdn.shopify.com/')===0 ? u+(u.indexOf('?')<0?'?':'&')+'width='+w : u; }   // il CDN Shopify ridimensiona con ?width=\n  async function copyCode(code, btn){\n    track('tap','copy_code');\n    try{ await navigator.clipboard.writeText(code); toast('Codice copiato'); if(btn){ const old=btn.textContent; btn.textContent='Copiato'; setTimeout(()=>{ btn.textContent=old; },1800); } }\n    catch(_){ toast('Codice: '+code); }\n  }\n\n  // === finestre (memory, premio): fuoco dentro all'apertura, Esc chiude, il fuoco torna dov'era ===\n  let lastFocus=null;\n  function openModal(id, focusNode){ const m=el(id); lastFocus=document.activeElement; m.classList.add('on'); m.setAttribute('aria-hidden','false'); setTimeout(()=>{ const f=focusNode||m.querySelector('button:not([disabled])'); if(f) f.focus(); },80); }\n  function closeModal(id){ const m=el(id); if(!m.classList.contains('on')) return; m.classList.remove('on'); m.setAttribute('aria-hidden','true'); const back=(lastFocus && lastFocus!==document.body && document.contains(lastFocus)) ? lastFocus : el('redeem'); if(back && back.focus) back.focus(); }   // il bottone di partenza puo' essere stato ridisegnato: si torna alla card dei punti\n  document.addEventListener('keydown', e=>{ if(e.key==='Escape'){ closeModal('gameModal'); closeModal('rewardModal'); } });\n  function reward(title,prize,msg,code){\n    el('rewardTitle').textContent=title; el('rewardPrize').textContent=prize; el('rewardMsg').textContent=msg||'';\n    el('rewardCode').innerHTML = code ? '<div class=\"codechip\"><span class=\"c\">'+esc(code)+'</span><button class=\"cp tap\" type=\"button\" data-code=\"'+esc(code)+'\">Copia</button></div>' : '';\n    openModal('rewardModal', el('rewardOk')); confetti();\n  }\n  el('rewardOk').addEventListener('click', ()=>closeModal('rewardModal'));\n  el('rewardCode').addEventListener('click', e=>{ const cp=e.target.closest('.cp'); if(cp) copyCode(cp.dataset.code||'', cp); });\n\n  // === stati della pagina ===\n  function loginUrl(){ return '/customer_authentication/login?return_to='+encodeURIComponent(location.pathname+location.search); }   // account clienti nuovi: dopo l'accesso si torna qui (anche con ?evento=)\n  function showGate(title,msg,mode){\n    el('loading').classList.add('hidden'); el('app').classList.add('hidden'); const g=el('gate'); g.classList.remove('hidden');\n    el('gateTitle').textContent=title; el('gateMsg').textContent=msg;\n    const login = mode===true || mode==='login';\n    el('gateBtn').classList.toggle('hidden',!login); if(login) el('gateBtn').href=loginUrl();\n    el('gateRetry').classList.toggle('hidden', mode!=='retry');\n  }\n  el('gateRetry').addEventListener('click', ()=>{ el('gate').classList.add('hidden'); el('loading').classList.remove('hidden'); refresh(false); });\n\n  // === render ===\n  function reward0(){ const rd=S && S._rewards; return (rd && Array.isArray(rd.rewards) && rd.rewards.length) ? rd.rewards[0] : null; }   // primo premio attivo (oggi 'amica12')\n  function percento(o){ return (o && (o.kind==null || o.kind==='percentage') && Number(o.value)>0) ? Number(o.value) : 0; }           // \"%\" solo per un premio a percentuale; 0 = premio di altro tipo\n\n  function render(){\n    el('loading').classList.add('hidden'); el('gate').classList.add('hidden'); el('app').classList.remove('hidden');\n    const p = S.points||0;\n    countUp(el('pts'), p);\n    renderRedeem(); renderCodes(); renderBonus2(); renderBirthday(); renderProfile(); renderRules();\n    // Mimi' e le azioni del giorno\n    parla(false);\n    el('mimi').setAttribute('aria-label', S.coccola_disponibile ? 'Coccola Mimì: +5 punti, una al giorno' : 'Mimì: toccala per sentire cosa dice');\n    const bc=el('btnCoccola');\n    if(!S.coccola_disponibile){ bc.className='act done'; bc.innerHTML=ICO_MIMI+'Coccolata<small>torna domani</small>'; }\n    else { bc.className='act main tap'; bc.innerHTML=ICO_MIMI+'Coccola Mimì<small>+5 punti, una al giorno</small>'; }\n    bc.setAttribute('aria-disabled', String(!S.coccola_disponibile));\n    const bg=el('btnGame');\n    if(!S.memory_disponibile){ bg.className='act done'; bg.innerHTML=ICO_CARTA+'Giocato<small>torna domani</small>'; }\n    else { bg.className='act tap'; bg.innerHTML=ICO_CARTA+'Gioca al memory<small>+5 punti, una al giorno</small>'; }\n    bg.setAttribute('aria-disabled', String(!S.memory_disponibile));\n    // le tue borse (quelle realmente acquistate)\n    const w=el('ward'), items=S.wardrobe;\n    if(items===null){ w.className='empty'; w.innerHTML='Le tue borse non sono leggibili in questo momento: riprova fra poco.'; }   // null = non leggibile (audit), diverso da \"nessuna borsa\"\n    else if(!items||!items.length){ w.className='empty mimi'; w.innerHTML='<img alt=\"\" src=\"'+MIMI+'\"><span>Le borse che compri su amimi.it appariranno qui. <a href=\"/\" id=\"shopLink\">Guarda le novità</a></span>'; }\n    else { w.className='ward'; w.innerHTML=items.map(it=>'<figure class=\"witem\">'+(it.img ? '<img src=\"'+esc(thumb(it.img,300))+'\" alt=\"\" loading=\"lazy\">' : '<div class=\"noimg\"></div>')+'<figcaption>'+esc(it.titolo||it.codice)+'</figcaption></figure>').join(''); }\n    // per ultimo e contenuto: il sentiero e' un disegno, se il browser non riesce a misurarlo sparisce lui e il resto della pagina (riscatto, codici, azioni) resta\n    try { renderPath(); } catch(e) { roadStop(); el('walk').classList.add('hidden'); el('pronti').classList.add('hidden'); }\n  }\n\n  // === Mimi' parla (owner 12-10: \"piu' presente\"). Nel fumetto accanto al saluto dice, in prima persona, la prima frase\n  // che vale per lo stato; a coccola fatta ogni tocco passa alla frase dopo. `una` = frase d'occasione (vittoria al memory,\n  // presenza a un evento, riscatto): resta finche' non cambia lo stato o non la si tocca. Le frasi stanno tutte qui.\n  let fraseK='', fraseI=0, fraseUna='';\n  function frasi(){\n    const rw=reward0(), p=S.points||0, cost=rw ? Number(rw.cost_points) : 0, pc=percento(rw), out=[];\n    const attesa=((S._rewards && S._rewards.redemptions) || []).some(x=>x.status==='pending');\n    const pronto = cost>0 && p>=cost && !attesa;\n    out.push(S.coccola_disponibile ? 'Mi fai la coccola di oggi? Toccami!' : 'Che bella coccola! Oggi sono al settimo cielo.');\n    if(pronto) out.push(pc ? 'Hai uno sconto pronto. Lo usiamo?' : 'Hai un premio pronto. Lo usiamo?');\n    if(S.memory_disponibile) out.push('Giochiamo al memory con le nostre borse?');\n    if(cost>0 && !pronto && !attesa){ const m=cost-(p%cost); out.push('Ancora '+(m===1 ? '1 punto' : m+' punti')+' e '+(pc ? 'lo sconto' : 'il premio')+' è tuo.'); }\n    if(!S.coccola_disponibile && !S.memory_disponibile) out.push('Per oggi abbiamo fatto tutto. Ti aspetto domani!');\n    return out;\n  }\n  function parla(avanti, una){\n    const f=frasi(), k=f.join('|'), m=el('mood');\n    if(k!==fraseK){ fraseK=k; fraseI=0; fraseUna=''; }\n    else if(avanti){ if(fraseUna) fraseUna=''; else fraseI=(fraseI+1)%f.length; }\n    if(una) fraseUna=una;\n    const t=fraseUna || f[fraseI];\n    if(m.textContent===t) return;\n    m.textContent=t; const b=m.parentNode; b.classList.remove('new'); void b.offsetWidth; b.classList.add('new');   // il fumetto si riaffaccia a ogni frase nuova\n  }\n\n  // === il sentiero a giro (scelta owner 12-10): un giro = <costo del premio> punti = un premio. Tappe a un quarto, meta' e\n  // tre quarti del costo, bandierina grande al traguardo. Mimi' sta alla FRAZIONE del giro in corso (data-f, da 0 a 1):\n  // riscattare scala un giro intero, quindi lei resta dov'e' e cala solo il numero di premi pronti. ===\n  const ROAD_VB = [320, 260];\n  let roadC=null, roadRaf=0, roadEnd=0;                                                   // roadC = punti/costo gia' disegnati (giri, con la virgola)\n  // Frazione del giro. A un multiplo esatto del costo Mimi' e' SUL traguardo solo quando e' un ARRIVO (saldo fermo li');\n  // mentre cammina, un numero intero di giri e' la partenza del giro dopo: senza questa distinzione chi apre la pagina con\n  // 257 punti vedrebbe per un attimo la bandierina festeggiare un traguardo che non sta raggiungendo.\n  function giro(c, arrivo){ const f=c-Math.floor(c); return (arrivo && c>0 && f<1e-9) ? 1 : f; }\n  function sparkAt(host,left,top){ if(reduced) return; for(let i=0;i<5;i++){ setTimeout(()=>{ const z=document.createElement('i'); z.className='spark'; z.style.width=z.style.height='12px'; z.style.left='calc('+left+' + '+(Math.random()*26-6)+'px)'; z.style.top='calc('+top+' - '+(16+Math.random()*16)+'px)'; host.appendChild(z); setTimeout(()=>z.remove(),1300); }, i*70); } }\n  function festa(w){ if(reduced) return; const goal=w.querySelector('.goal'); goal.classList.remove('pop'); void goal.offsetWidth; goal.classList.add('pop'); sparkAt(w, goal.style.left, goal.style.top); }   // scatto della bandierina e scintille\n  function roadDraw(w, c, arrivo, quiet){\n    const f=giro(c, arrivo), pt=w._path.getPointAtLength(w._len*f), run=w.querySelector('.runner');\n    run.style.left=(pt.x/ROAD_VB[0]*100)+'%'; run.style.top=(pt.y/ROAD_VB[1]*100)+'%';\n    w.querySelector('.r-fg').setAttribute('stroke-dasharray',(f*100).toFixed(2)+' 100');\n    w.querySelectorAll('.stop').forEach(z=>{ const on=f*100>=Number(z.dataset.at)-0.01; z.classList.toggle('on',on); z.querySelector('.lbl').classList.toggle('on',on); });\n    const goal=w.querySelector('.goal'), on=f>=1, era=goal.classList.contains('on');\n    goal.classList.toggle('on',on); w.querySelector('.lbl.fine').classList.toggle('on',on);\n    if(on && !era && !quiet) festa(w);\n    w.dataset.f=f.toFixed(4);\n  }\n  function roadStop(){ cancelAnimationFrame(roadRaf); clearTimeout(roadEnd); }\n  function renderPath(){\n    const w=el('walk'), pr=el('pronti'), rw=reward0(), p=S.points||0;\n    if(!rw || !(Number(rw.cost_points)>0)){ roadStop(); w.classList.add('hidden'); pr.classList.add('hidden'); return; }   // senza catalogo premi restano solo i punti\n    const cost=Number(rw.cost_points), k=Math.floor(p/cost), c=p/cost, resto=p%cost, sconto=percento(rw)>0;\n    const attesa=((S._rewards && S._rewards.redemptions) || []).some(x=>x.status==='pending');   // un riscatto in attesa blocca il prossimo: niente \"pronti\" finche' non arriva il codice\n    w.classList.remove('hidden');                                                         // prima visibile, poi si misura il tracciato\n    if(w.dataset.cost!==String(cost)){\n      const path=w.querySelector('.r-bg'), len=path.getTotalLength(); w._path=path; w._len=len;\n      let h='';\n      [0.25,0.5,0.75].forEach(q=>{ const pt=path.getPointAtLength(len*q); h+='<g class=\"stop\" data-at=\"'+(q*100)+'\"><circle cx=\"'+pt.x.toFixed(1)+'\" cy=\"'+pt.y.toFixed(1)+'\" r=\"7\"/><text class=\"lbl\" x=\"'+pt.x.toFixed(1)+'\" y=\"'+(pt.y+(q===0.5?-15:22)).toFixed(1)+'\" text-anchor=\"middle\">'+Math.round(cost*q)+'</text></g>'; });\n      const end=path.getPointAtLength(len), goal=w.querySelector('.goal');\n      h+='<text class=\"lbl fine\" x=\"'+(end.x+2).toFixed(1)+'\" y=\"'+(end.y+30).toFixed(1)+'\" text-anchor=\"middle\">'+cost+'</text>';   // sotto la fine della strada, fuori dal tracciato\n      el('roadMarks').innerHTML=h;\n      goal.style.left=(end.x/ROAD_VB[0]*100)+'%'; goal.style.top=(end.y/ROAD_VB[1]*100)+'%';\n      w.dataset.cost=String(cost);\n    }\n    // premi pronti: una bandierina per giro completato (al massimo cinque disegnate, il numero e' scritto)\n    if(k>0 && !attesa){ let h=''; for(let i=0;i<Math.min(k,5);i++) h+='<span class=\"flag on\"><i></i></span>'; pr.innerHTML=h+'<em>'+(k===1 ? (sconto?'1 sconto pronto':'1 premio pronto') : k+(sconto?' sconti pronti':' premi pronti'))+'</em>'; pr.classList.remove('hidden'); }\n    else { pr.innerHTML=''; pr.classList.add('hidden'); }\n    w.setAttribute('aria-label','Hai '+p+(p===1?' punto':' punti')+' Mimì. '+((p>0 && resto===0) ? 'Sei al traguardo del giro.' : 'Sei a '+resto+(resto===1?' punto':' punti')+' su '+cost+' del giro verso il prossimo '+(sconto?'sconto':'premio')+'.'));\n    // movimento: la prima volta dall'inizio del giro in corso; poi solo in avanti. Un saldo che scende (riscatto) non fa camminare all'indietro.\n    const run=w.querySelector('.runner');\n    roadStop();\n    const from = roadC===null ? ((p>0 && resto===0) ? c-1 : Math.floor(c)) : roadC;\n    const fine=()=>{ roadStop(); roadC=c; roadDraw(w,c,true,false); run.classList.remove('go'); };\n    if(reduced || c<=from){ roadC=c; roadDraw(w,c,true,true); run.classList.remove('go'); return; }\n    const d=Math.max(650, Math.min(2400, (c-from)*2000)), t0=performance.now();\n    run.classList.add('go');\n    (function step(t){\n      const x=Math.min(1,(t-t0)/d), e=x<.5 ? 2*x*x : 1-Math.pow(-2*x+2,2)/2, prima=roadC===null ? from : roadC;\n      roadC=from+(c-from)*e;                                                              // roadC segue Mimi': se arriva un altro saldo a meta' strada si riparte da dov'e'\n      roadDraw(w, roadC, false, false);\n      if(x<1 && Math.floor(roadC)>Math.floor(prima)) festa(w);                            // ha passato il traguardo in corsa (es. da 95 a 110): si festeggia al passaggio\n      if(x<1) roadRaf=requestAnimationFrame(step); else fine();\n    })(t0);\n    roadEnd=setTimeout(fine, d+250);                                                      // arrivo garantito anche a fotogrammi fermi (scheda in secondo piano)\n  }\n\n  // === riscatto (punti -> codice sconto). Catalogo e riscatti dall'edge (azioni rewards/redeem). ===\n  function renderRedeem(){\n    const box=el('redeem'), out=el('redeemBox'), st=el('pathStatus'), rd=S && S._rewards, rw=reward0();\n    if(!rw){ out.innerHTML=''; st.innerHTML=''; delete box.dataset.trk; return; }\n    const p=S.points||0, reds=rd.redemptions||[], cost=Number(rw.cost_points), k=Math.floor(p/cost), manca=cost-(p%cost);\n    const pending=reds.find(x=>x.status==='pending');\n    const punti = manca===1 ? '1 punto' : manca+' punti', pc=percento(rw);\n    box.dataset.trk = pending ? 'redeem_pending' : (p>=rw.cost_points ? 'redeem_ready' : 'redeem_locked');   // letto dal tracciamento quando la card entra in vista\n    if(pending){ st.innerHTML='Riscatto ricevuto. Il tuo codice sta arrivando.'; out.innerHTML=''; return; }\n    if(p>=rw.cost_points){\n      // il riscatto e' RIPETIBILE: uno sconto ogni <cost> punti\n      const cosa = pc ? (k===1 ? '1 sconto del '+pc+'%' : k+' sconti del '+pc+'%') : (k===1 ? '1 premio' : k+' premi');\n      st.innerHTML='Hai <b>'+cosa+'</b> da riscattare. Il prossimo fra '+punti+'.';\n      out.innerHTML='<button class=\"rbtn tap\" type=\"button\" id=\"rbtn\" data-reward=\"'+esc(rw.key)+'\">Riscatta '+(pc ? 'il '+pc+'%' : 'il premio')+' · '+cost+' punti</button>';\n    } else {\n      st.innerHTML=(manca===1 ? 'Ti manca' : 'Ti mancano')+' <b>'+punti+'</b> '+(pc ? 'allo sconto del '+pc+'%' : 'al premio')+'.';\n      out.innerHTML='';\n    }\n  }\n\n  // === i tuoi codici: TUTTI i riscatti, prima quelli da usare. used_at arriva dal server (il codice compare in un ordine). ===\n  function renderCodes(){\n    const sec=el('codiciSec'), ul=el('codici'), more=el('codiciTutti'), rd=S && S._rewards, rw=reward0();\n    const reds=(rd && Array.isArray(rd.redemptions)) ? rd.redemptions.filter(x=>x.status==='pending' || (x.status==='fulfilled' && x.discount_code)) : [];\n    if(!reds.length){ sec.classList.add('hidden'); return; }\n    sec.classList.remove('hidden');\n    const rank=x=> x.status==='pending' ? 0 : (x.used_at ? 2 : 1);\n    const list=reds.slice().sort((a,b)=> rank(a)-rank(b) || String(b.created_at||'').localeCompare(String(a.created_at||'')));\n    const vis = tuttiICodici ? list : list.slice(0, CONFIG.codiciVisibili);\n    ul.innerHTML=vis.map(x=>{\n      const pc = percento(x) || ((x.kind==null && rw && x.reward_key===rw.key) ? percento(rw) : 0);   // tipo e valore dal server; un server v13 non li manda: allora quelli del premio attivo, se e' lo stesso\n      const cosa = pc ? pc+'% di sconto' : 'Sconto';\n      // i giorni arrivano dal server gia' in Europe/Rome (created_day, used_day); col server v13 si ripiega sulla data UTC\n      if(x.status==='pending') return '<li class=\"cod\"><div class=\"cod-main\"><span class=\"cod-c\">In arrivo</span><span class=\"cod-m\">'+cosa+', riscattato il '+esc(itDate(x.created_day||x.created_at))+'</span></div><span class=\"chip\">In preparazione</span></li>';\n      if(x.used_at) return '<li class=\"cod used\"><div class=\"cod-main\"><span class=\"cod-c\">'+esc(x.discount_code)+'</span><span class=\"cod-m\">'+cosa+', usato il '+esc(itDate(x.used_day||x.used_at))+'</span></div><span class=\"chip\">Usato</span></li>';\n      return '<li class=\"cod\"><div class=\"cod-main\"><span class=\"cod-c\">'+esc(x.discount_code)+'</span><span class=\"cod-m\">'+cosa+', da usare al checkout</span></div><button class=\"cp tap\" type=\"button\" data-code=\"'+esc(x.discount_code)+'\">Copia</button></li>';\n    }).join('');\n    if(list.length>CONFIG.codiciVisibili){ more.classList.remove('hidden'); more.textContent = tuttiICodici ? 'Mostra meno' : 'Mostra tutti ('+list.length+')'; }\n    else more.classList.add('hidden');\n  }\n  el('codici').addEventListener('click', e=>{ const cp=e.target.closest('.cp'); if(cp) copyCode(cp.dataset.code||'', cp); });\n  el('codiciTutti').addEventListener('click', ()=>{ track('tap','codici_tutti'); tuttiICodici=!tuttiICodici; renderCodes(); });\n\n  // === come prendi i punti: le regole decise nella call del 09-10; costo e valore del premio dal server ===\n  function renderRules(){\n    const rw=reward0(), pr=S._profile;\n    const rows=[['Compri su amimi.it','1 punto per ogni euro'],['Coccoli Mimì','+5 al giorno'],['Giochi al memory','+5 al giorno']];\n    if(pr && pr.checkin_enabled) rows.push(['Vieni a un evento Amimì','+20 con il QR']);\n    el('regole').innerHTML=rows.map(r=>'<li><span>'+esc(r[0])+'</span><b>'+esc(r[1])+'</b></li>').join('');\n    el('regoleNota').innerHTML = rw ? 'Ogni <b>'+esc(rw.cost_points)+' punti Mimì</b> sblocchi '+(percento(rw) ? 'uno sconto del <b>'+percento(rw)+'%</b>' : esc(rw.label))+' su un ordine. Quando lo riscatti i punti si scalano. Il codice vale una volta e non si somma ad altri sconti.' : '';\n  }\n  el('ward').addEventListener('click', e=>{ if(e.target.closest('#shopLink')) track('tap','shop'); });\n\n  // === compleanno, seconda borsa, profilo (v12: azione profile; a flag OFF tutto resta nascosto) ===\n  function renderBirthday(){\n    const b=el('bday'), pr=S._profile;\n    if(!pr || !pr.profile_enabled || !pr.birthday_today){ b.classList.add('hidden'); return; }\n    b.classList.remove('hidden');\n    b.innerHTML='<span class=\"flag on\"><i></i></span><span class=\"txt\"><b>Buon compleanno!</b>Mimì ti fa tanti auguri'+(pr.birthday_awarded ? ': +20 punti Mimì di regalo sul tuo saldo.' : '.')+'</span>';\n  }\n  function renderBonus2(){\n    const b=el('bonus2'), pr=S._profile, bs=pr && pr.bonus_second_enabled ? pr.bonus_second : null;\n    if(!bs){ b.classList.add('hidden'); return; }\n    if(bs.awarded){ b.classList.remove('hidden'); b.innerHTML='Bonus seconda borsa ricevuto: <b>+50 punti</b>'; return; }\n    if(bs.ordini===1 && bs.deadline){\n      const gg=Math.max(0, Number(bs.days_left)||0);   // giorni calcolati dal server in Europe/Rome, mai dal fuso del browser\n      b.classList.remove('hidden');\n      b.innerHTML='Seconda borsa entro il <b>'+esc(itDate(bs.deadline))+'</b>: <b>+50 punti</b>'+(gg>0 ? ', mancano '+gg+(gg===1?' giorno':' giorni') : ', scade oggi');\n      return;\n    }\n    b.classList.add('hidden');\n  }\n  function renderProfile(){\n    const sec=el('profSec'), box=el('profilo'), pr=S._profile;\n    if(!pr || !pr.profile_enabled){ sec.classList.add('hidden'); return; }\n    sec.classList.remove('hidden');\n    const P=pr.profile||{};\n    const consenso='<div class=\"chk\"><input type=\"checkbox\" id=\"pConsenso\" '+(P.consenso_compleanno?'checked':'')+'><label for=\"pConsenso\">Voglio il regalo di compleanno. Usiamo solo giorno e mese per farti un regalo di compleanno. Niente anno.</label></div>';\n    if(P.complete){\n      box.innerHTML='<div class=\"sum\">Compleanno: <b>'+esc(P.birth_day)+' '+esc(CONFIG.mesi[(P.birth_month||1)-1]||'')+'</b><br>Materiale preferito: <b>'+esc(P.materiale_preferito||'')+'</b><br>Regalo di compleanno: <b>'+(P.consenso_compleanno?'sì':'no')+'</b></div>'\n        +'<span class=\"got\">+10 punti ricevuti</span>'\n        +consenso\n        +'<button class=\"sbtn tap\" type=\"button\" id=\"pSave\">Aggiorna</button>'\n        +'<div class=\"pnote\">La data di compleanno non si modifica da qui: per una correzione scrivi all\\'assistenza.</div>';\n      return;\n    }\n    const locked=!!P.birth_locked;\n    let days=''; for(let d=1;d<=31;d++) days+='<option value=\"'+d+'\"'+(P.birth_day===d?' selected':'')+'>'+d+'</option>';\n    let months=''; CONFIG.mesi.forEach((m,i)=>{ months+='<option value=\"'+(i+1)+'\"'+(P.birth_month===i+1?' selected':'')+'>'+esc(m)+'</option>'; });\n    let mats=''; CONFIG.materiali.forEach(m=>{ mats+='<option value=\"'+esc(m)+'\"'+(P.materiale_preferito===m?' selected':'')+'>'+esc(m)+'</option>'; });\n    box.innerHTML='<div class=\"pnote\" style=\"margin-top:0\">Completa il profilo e ricevi <b>+10 punti</b>. Il giorno del tuo compleanno Mimì ti regala <b>+20 punti</b>.</div>'\n      +'<div class=\"row\"><div style=\"flex:1\"><label for=\"pDay\">Giorno</label><select id=\"pDay\"'+(locked?' disabled':'')+'><option value=\"\">-</option>'+days+'</select></div>'\n      +'<div style=\"flex:2\"><label for=\"pMonth\">Mese</label><select id=\"pMonth\"'+(locked?' disabled':'')+'><option value=\"\">-</option>'+months+'</select></div></div>'\n      +'<div class=\"row\"><div style=\"flex:1\"><label for=\"pMat\">Materiale preferito</label><select id=\"pMat\"><option value=\"\">-</option>'+mats+'</select></div></div>'\n      +consenso\n      +'<button class=\"sbtn tap\" type=\"button\" id=\"pSave\">Salva il profilo</button>'\n      +(locked ? '<div class=\"pnote\">La data di compleanno è già salvata e non si modifica da qui.</div>' : '<div class=\"pnote\">Il regalo di compleanno arriva se il profilo è salvato almeno 30 giorni prima.</div>');\n  }\n  el('profilo').addEventListener('click', async e=>{\n    const btn=e.target.closest('#pSave'); if(!btn||!S) return;\n    track('tap','profile_save');\n    const day=el('pDay'), month=el('pMonth'), mat=el('pMat'), cons=el('pConsenso');\n    const body={ consenso: !!(cons && cons.checked) };\n    if(day && !day.disabled && day.value) body.birth_day=Number(day.value);\n    if(month && !month.disabled && month.value) body.birth_month=Number(month.value);\n    if(mat && mat.value) body.materiale=mat.value;\n    if(day && !day.disabled && ((body.birth_day && !body.birth_month) || (!body.birth_day && body.birth_month))){ toast('Scegli giorno e mese'); return; }\n    btn.disabled=true; btn.textContent='Salvo...';\n    const { data } = await api('profile_save',{method:'POST',body});\n    if(data && data.ok){\n      await refresh(false);\n      if(data.awarded) reward('Profilo completo!', '+10', 'punti Mimì aggiunti al tuo saldo');\n      else toast(data.birthday_locked ? 'Profilo aggiornato (la data resta quella salvata)' : 'Profilo aggiornato');\n    } else if(data && data.error==='bad_date'){ toast('Questa data non esiste'); btn.disabled=false; btn.textContent='Salva il profilo'; }\n    else { toast('Riprova fra poco'); btn.disabled=false; btn.textContent='Riprova'; }\n  });\n\n  async function refresh(animate){\n    const [st, rw, pf] = await Promise.all([api('state'), api('rewards'), api('profile')]);   // rewards/profile: OFF finche' i flag sono spenti\n    const { status, data } = st;\n    if (data.state==='login_required') return showGate(EVT ? 'Accedi per registrare la tua presenza' : 'I tuoi punti Mimì', EVT ? 'Entra con il tuo account Amimì, oppure creane uno in un minuto. Se l\\'evento è in corso, i punti arrivano subito dopo.' : 'Accedi con il tuo account Amimì per vedere i tuoi punti e coccolare Mimì.', 'login');\n    if (data.state==='needs_secret' || data.state==='off') return showGate('I punti Mimì stanno arrivando','Il programma parte a breve. Torna presto!', '');\n    if (status===503 || data.error || typeof data.points!=='number') return showGate('Un attimo...','Non riesco a leggere i tuoi punti in questo momento.', 'retry');   // senza un saldo vero non si disegna nessun profilo\n    S = data;\n    S._rewards = (rw && rw.data && Array.isArray(rw.data.rewards)) ? rw.data : null;\n    S._profile = (pf && pf.status===200 && pf.data && !pf.data.error && typeof pf.data.profile_enabled==='boolean') ? pf.data : null;   // non leggibile = come a flag OFF, mai una card finta\n    render();\n    trackStart();\n    checkin();\n  }\n\n  // === presenza a un evento dal QR: amimi.it/apps/premia/club?evento=CODICE ===\n  // Il codice resta in attesa (localStorage) se serve prima l'accesso. I punti li decide il server: finestra oraria\n  // dell'evento, una presenza per cliente, tetto. Qui si mostra solo l'esito.\n  const EVT_KEY='mimi_evento';\n  function evtStored(){ try{ const o=JSON.parse(localStorage.getItem(EVT_KEY)||'null'); return (o && o.c && Date.now()-o.t < CONFIG.eventoOre*3600000) ? String(o.c) : ''; }catch(_){ return ''; } }\n  function evtClear(){ EVT=''; try{ localStorage.removeItem(EVT_KEY); }catch(_){}\n    try{ const u=new URL(location.href); if(u.searchParams.has('evento')){ u.searchParams.delete('evento'); history.replaceState(null,'',u.pathname+u.search+u.hash); } }catch(_){} }\n  let EVT=(()=>{ let c=''; try{ c=(new URLSearchParams(location.search).get('evento')||'').trim().toUpperCase(); }catch(_){}\n    if(/^[A-Z0-9_-]{4,40}$/.test(c)){ try{ localStorage.setItem(EVT_KEY, JSON.stringify({ c:c, t:Date.now() })); }catch(_){} return c; }\n    return evtStored(); })();\n  let evtBusy=false;\n  function evtNote(title,msg,retry){\n    const n=el('evento'); n.classList.remove('hidden');\n    n.innerHTML='<span class=\"flag on\"><i></i></span><span class=\"txt\"><b>'+esc(title)+'</b>'+esc(msg)+'</span>'+(retry ? '<button class=\"mini tap\" type=\"button\" id=\"evtRetry\">Riprova</button>' : '');\n  }\n  el('evento').addEventListener('click', e=>{ if(e.target.closest('#evtRetry')) checkin(); });\n  async function checkin(){\n    if(!EVT || !S || evtBusy) return;\n    evtBusy=true;\n    const { data } = await api('checkin',{method:'POST',body:{code:EVT}});\n    evtBusy=false;\n    const nome = data && data.label ? String(data.label) : 'questo evento';\n    if(data && data.state==='off'){ evtClear(); evtNote('Presenze non attive', 'In questo momento i punti degli eventi non si possono prendere.'); return; }\n    if(data && data.ok && !data.already){\n      evtClear(); S.points=data.points; render();\n      evtNote('Presenza registrata', '+'+(data.added||0)+' punti Mimì per '+nome+'.');\n      reward('Eccoti qui!', '+'+(data.added||0), 'punti Mimì per '+nome); parla(false,'Che bello vederti qui!');\n      return;\n    }\n    if(data && data.ok && data.already){ evtClear(); evtNote('Punti già presi', 'La tua presenza per '+nome+' è già registrata.'); return; }\n    const r = data && data.reason;\n    if(r==='not_started'){ evtNote('Non è ancora ora', 'I punti per '+nome+' si prendono durante l\\'evento. Riprova quando sei lì.', true); return; }   // il codice resta in attesa\n    if(r==='ended'){ evtClear(); evtNote('Evento finito', 'I punti per '+nome+' non sono più disponibili.'); return; }\n    if(r==='full'){ evtClear(); evtNote('Punti esauriti', 'I punti per '+nome+' sono finiti.'); return; }\n    if(r==='unknown_event'){ evtClear(); evtNote('QR non valido', 'Questo codice evento non esiste. Chiedi a noi di Amimì.'); return; }\n    evtNote('Presenza non registrata', 'Non riesco a registrare la tua presenza in questo momento.', true);\n  }\n\n  // === azioni ===\n  let coccolaInCorso=false;                                                               // un tap alla volta: il secondo non parte finche' il primo non ha risposta\n  async function coccola(){\n    if(!S || !S.coccola_disponibile || coccolaInCorso) return;\n    coccolaInCorso=true; track('tap','coccola');\n    const { data } = await api('coccola');\n    coccolaInCorso=false;\n    if(data.done_today){ S.coccola_disponibile=false; if(typeof data.points==='number') S.points=data.points; render(); toast('Mimì è già stata coccolata oggi'); return; }\n    if(data.error || typeof data.points!=='number'){ toast('Riprova fra poco'); return; }   // solo un saldo vero dal server muove i punti\n    S.points=data.points; S.coccola_disponibile=false; squee(); sparkles(el('mimi'),7); render(); toast('+'+(data.added||5)+' punti Mimì, coccola di oggi fatta');\n  }\n  el('btnCoccola').addEventListener('click', coccola);\n  // toccare Mimi' e' farle la coccola (stessa strada del bottone: un tap alla volta, una al giorno); a coccola fatta risponde con la frase dopo\n  el('mimi').addEventListener('click', ()=>{ if(!S) return; if(S.coccola_disponibile){ coccola(); return; } squee(); parla(true); });\n  el('shopFine').addEventListener('click', ()=>track('tap','shop'));\n\n  // riscatto (bottone disabilitato subito = anti doppio-click; idemp lato server).\n  // UN solo token per tentativo: se la risposta si perde (rete, 5xx) il \"Riprova\" rimanda LO STESSO token, cosi' il\n  // server riconosce il riscatto gia' fatto (ramo already) e non scala i punti una seconda volta. Il token si butta solo\n  // davanti a una risposta definitiva del server (riuscito, oppure rifiutato con un motivo).\n  let idempRiscatto=null;\n  el('redeem').addEventListener('click', async e=>{\n    const btn=e.target.closest('#rbtn'); if(!btn||!S) return;\n    track('tap','redeem');\n    const rw=reward0()||{};\n    const pct=percento(rw)?('-'+percento(rw)+'%'):'Premio';\n    btn.disabled=true; btn.textContent='Riscatto...';\n    const idemp = idempRiscatto || (idempRiscatto='r-'+Date.now()+'-'+Math.random().toString(36).slice(2,10));\n    const { data } = await api('redeem',{method:'POST',body:{reward:btn.dataset.reward, idemp}});\n    if(data && data.ok){\n      idempRiscatto=null;\n      await refresh(false);\n      if(data.code){ reward(percento(rw) ? 'Sconto sbloccato!' : 'Premio sbloccato!', pct, 'Usalo al checkout. Vale una volta e non si somma ad altri sconti.', data.code); parla(false,'Buono shopping! Poi mi racconti.'); }\n      else toast('Riscatto ricevuto, codice in arrivo');\n    } else if(data && data.reason){\n      idempRiscatto=null;                                                                 // rifiuto con motivo: i punti non sono stati toccati\n      if(typeof data.points==='number') S.points=data.points;\n      toast(data.reason==='insufficient' ? 'Punti non sufficienti' : 'Riscatto non disponibile in questo momento'); render();\n    }\n    else { toast('Riprova fra poco'); btn.disabled=false; btn.textContent='Riprova'; }\n  });\n\n  // === memory con le foto vere: il mazzo arriva dall'edge (azione deck), il premio lo decide memory_win ===\n  let DECK=null;                                                                          // null = non ancora chiesto\n  const RISERVA=[{ g:'mimi' },{ g:'chk' },{ g:'word' }];                                  // mazzo di riserva se le foto non arrivano\n  function preload(u){ return new Promise(res=>{ const i=new Image(); let done=false; const end=ok=>{ if(done) return; done=true; res(ok ? u : null); }; i.onload=()=>end(true); i.onerror=()=>end(false); setTimeout(()=>end(false),5000); i.src=u; }); }\n  async function loadDeck(){\n    if(DECK) return DECK;\n    const { status, data } = await api('deck');\n    const cards=(status===200 && data && Array.isArray(data.cards)) ? data.cards.filter(c=>c && c.img) : [];\n    const ok=(await Promise.all(cards.map(c=>preload(thumb(c.img,360))))).map((u,i)=> u ? { img:u, titolo:String(cards[i].titolo||'Borsa Amimì') } : null).filter(Boolean);\n    DECK = ok.length>=CONFIG.coppie ? ok.slice(0,CONFIG.coppie) : RISERVA;\n    return DECK;\n  }\n  function faceHTML(c){\n    if(c.img) return '<span class=\"front\"><img alt=\"\" src=\"'+esc(c.img)+'\"></span>';\n    if(c.g==='mimi') return '<span class=\"front glyph\"><img alt=\"\" src=\"'+MIMI+'\"></span>';\n    if(c.g==='chk') return '<span class=\"front glyph chk\"></span>';\n    return '<span class=\"front glyph word\">amìmì</span>';\n  }\n  function faceName(c, i){ return c.img ? c.titolo : (c.g==='mimi' ? 'Mimì' : (c.g==='chk' ? 'Scacchi' : 'Amimì')); }\n  el('btnGame').addEventListener('click', ()=>{ if(!S||!S.memory_disponibile){ toast('Torna domani per un nuovo gioco'); return; } track('tap','gioco'); startGame(); });\n  el('gameClose').addEventListener('click', ()=>closeModal('gameModal'));\n  let partita=0;                                                                          // una sola partita alla volta riempie la griglia\n  async function startGame(){\n    const grid=el('grid'), n=CONFIG.coppie*2, mia=++partita;\n    let h=''; for(let i=0;i<n;i++) h+='<button class=\"card loading\" type=\"button\" disabled aria-label=\"Carta coperta\"><span class=\"in\"><span class=\"back\"><img alt=\"\" src=\"'+MIMI+'\"></span></span></button>';\n    grid.innerHTML=h; el('gameMsg').textContent='Preparo le carte...';\n    openModal('gameModal', el('gameClose'));\n    const deck=await loadDeck();\n    if(mia!==partita || !el('gameModal').classList.contains('on')) return;                // chiusa o riaperta mentre caricava\n    el('gameMsg').textContent='Abbina le borse uguali e vinci i punti di oggi.';\n    const order=[]; deck.forEach((c,i)=>{ order.push(i,i); }); order.sort(()=>Math.random()-0.5);\n    let up=[], matched=0, lock=false;\n    grid.querySelectorAll('.card').forEach((c,pos)=>{\n      const k=order[pos], face=deck[k];\n      c.dataset.k=String(k); c.querySelector('.in').insertAdjacentHTML('beforeend', faceHTML(face));\n      c.classList.remove('loading'); c.disabled=false;\n      c.addEventListener('click',()=>{\n        if(lock||c.classList.contains('up')||c.classList.contains('done'))return;\n        c.classList.add('up'); c.setAttribute('aria-label', faceName(face)); up.push(c);\n        if(up.length===2){ lock=true;\n          if(up[0].dataset.k===up[1].dataset.k){ up.forEach(x=>{ x.classList.add('done'); x.setAttribute('aria-label', faceName(deck[Number(x.dataset.k)])+', coppia trovata'); }); matched++; up=[]; lock=false;\n            const gm=el('gameMimi'); gm.classList.remove('hop'); void gm.offsetWidth; gm.classList.add('hop');   // Mimi' salta a ogni coppia trovata\n            if(matched===CONFIG.coppie) setTimeout(winGame,500);\n          } else setTimeout(()=>{ up.forEach(x=>{ x.classList.remove('up'); x.setAttribute('aria-label','Carta coperta'); }); up=[]; lock=false; },850);\n        }\n      });\n    });\n    const first=grid.querySelector('.card'); if(first) first.focus();\n  }\n  async function winGame(){\n    closeModal('gameModal');\n    const { data } = await api('memory_win');\n    if(data.done_today){ S.memory_disponibile=false; if(typeof data.points==='number') S.points=data.points; render(); toast('Hai già giocato oggi'); return; }\n    if(data.error || typeof data.points!=='number'){ toast('Riprova fra poco'); return; }   // solo un saldo vero dal server muove i punti\n    S.points=data.points; S.memory_disponibile=false; render();\n    reward('Hai vinto!', '+'+(data.added||5), 'punti Mimì aggiunti al tuo saldo'); parla(false,'Che memoria! Brava.');\n  }\n\n  refresh(false);\n})();\n</script>\n</body>\n</html>\n{% endraw %}";
const BODY_V1 = "{% layout none %}{% raw %}<!DOCTYPE html>\n<html lang=\"it\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Premia · Il mio profilo · Amimì</title>\n<!--\n  Area Membri \"Premia\" - PRODUZIONE (dati REALI via App Proxy).\n  Va servita SAME-ORIGIN su amimi.it (es. pagina/sezione storefront), cosi' le fetch a\n  /apps/premia/* portano il logged_in_customer_id firmato da Shopify (nessun secondo login).\n  Contratto edge live loyalty-proxy: state | balance | coccola | memory_win | nanna | wear | rewards | redeem | profile | profile_save.\n  Tiers e tessera sono calcolati lato client da CONFIG (nessun numero inventato lato server). Dal 22-09 (v12) il livello\n  segue i punti cumulati (server, azione profile) quando il flag loyalty_tier_lifetime_enabled e' acceso, altrimenti il saldo.\n  Card \"Il tuo profilo\" (compleanno giorno+mese, materiale, consenso) e riga \"seconda borsa\" solo a flag acceso: a flag OFF la pagina e' identica a prima.\n  Servita da github.io o altro dominio NON funziona: il cookie di login e' su amimi.it.\n-->\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --cream:#faf7f3; --paper:#fffdfa; --sand:#e4ded7; --ink:#2a2724; --muted:#6f6862;\n    --cognac:#8a6d4b; --bordeaux:#7a2e3f; --gold:#c9a86a; --peach:#f6e3d5; --blush:#f3d9d3; --ok:#5c7150;\n  }\n  *{box-sizing:border-box;margin:0;padding:0}\n  body{background:var(--cream);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;color:var(--ink);max-width:460px;margin:0 auto;padding:20px 16px 48px;min-height:100vh;position:relative;overflow-x:hidden}\n  .logo{font-family:\"Cormorant Garamond\",serif;font-style:italic;font-size:26px;color:var(--bordeaux);text-align:center;letter-spacing:1px}\n  h3.sec{font-size:11px;letter-spacing:2.5px;text-transform:uppercase;color:var(--cognac);margin:26px 0 10px}\n  .tap{cursor:pointer;-webkit-tap-highlight-color:transparent;user-select:none}.tap:active{opacity:.82}\n  .hidden{display:none!important}\n\n  /* stati (login / off / errore) */\n  .gate{text-align:center;padding:60px 20px}\n  .gate h2{font-family:\"Cormorant Garamond\",serif;font-size:30px;font-weight:600;margin-bottom:8px}\n  .gate p{font-size:13px;color:var(--muted);margin-bottom:20px;line-height:1.5}\n  .btn{display:inline-block;background:var(--bordeaux);color:#fff;font-size:13px;font-weight:700;padding:12px 22px;border-radius:99px;border:none;cursor:pointer;text-decoration:none}\n\n  /* mascotte Mimi */\n  .mimi{width:170px;height:170px;position:relative}\n  .mimi .handle{width:74px;height:52px;border:3px solid #3c2f28;border-bottom:none;border-radius:40px 40px 0 0;position:absolute;top:4px;left:48px}\n  .mimi .body{width:150px;height:118px;background:#fff;border:3px solid #3c2f28;border-radius:26px 26px 40px 40px;position:absolute;bottom:0;left:10px;box-shadow:inset 0 -14px 0 var(--blush)}\n  .mimi .clasp{width:22px;height:10px;background:var(--gold);border-radius:4px;position:absolute;bottom:104px;left:74px;border:2px solid #3c2f28;z-index:2}\n  .mimi .eye{width:12px;height:16px;background:#3c2f28;border-radius:50%;position:absolute;bottom:62px;animation:blink 4.5s infinite;z-index:2}\n  .mimi .eye.l{left:52px}.mimi .eye.r{right:52px}\n  .mimi .cheek{width:14px;height:8px;background:var(--blush);border-radius:50%;position:absolute;bottom:52px;z-index:2}\n  .mimi .cheek.l{left:38px}.mimi .cheek.r{right:38px}\n  .mimi .mouth{width:18px;height:9px;border:2.5px solid #3c2f28;border-top:none;border-radius:0 0 20px 20px;position:absolute;bottom:46px;left:76px;z-index:2}\n  .mimi .bow{position:absolute;top:44px;left:104px;z-index:3;display:none}\n  .mimi .bow i,.mimi .bow em{position:absolute;width:0;height:0;border-style:solid}\n  .mimi .bow i{border-width:9px 15px 9px 0;border-color:transparent var(--bordeaux) transparent transparent;left:-16px;top:-9px;transform:rotate(-8deg)}\n  .mimi .bow em{border-width:9px 0 9px 15px;border-color:transparent transparent transparent var(--bordeaux);left:1px;top:-9px;transform:rotate(8deg)}\n  .mimi .bow b{position:absolute;width:8px;height:8px;background:#5e2231;border-radius:50%;left:-5px;top:-4px}\n  .mimi.worn .bow{display:block}\n  @keyframes blink{0%,92%,96%,100%{transform:scaleY(1)}94%{transform:scaleY(.12)}}\n  @keyframes floaty{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}\n  @keyframes squee{0%{transform:scale(1)}30%{transform:scale(1.08) rotate(-2deg)}60%{transform:scale(.97) rotate(1.5deg)}100%{transform:scale(1)}}\n  .mimi.squee{animation:squee .7s ease}\n  .heart{position:absolute;z-index:70;pointer-events:none;animation:rise 1.3s ease-out forwards}\n  @keyframes rise{0%{opacity:0;transform:translateY(6px) scale(.7)}18%{opacity:1}100%{opacity:0;transform:translateY(-64px) scale(1.25)}}\n  .confetti{position:fixed;width:9px;height:14px;z-index:95;pointer-events:none;animation:fall linear forwards}\n  @keyframes fall{0%{opacity:1;transform:translateY(-10px) rotate(0)}100%{opacity:.9;transform:translateY(100vh) rotate(540deg)}}\n\n  /* profilo */\n  .hello{font-family:\"Cormorant Garamond\",serif;font-size:34px;font-weight:600;margin-top:14px;line-height:1.05}\n  .lvl{display:inline-flex;align-items:center;gap:7px;font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--cognac);margin-top:8px;background:var(--paper);border:1px solid var(--sand);padding:5px 11px;border-radius:99px}\n  .lvl .dot{width:8px;height:8px;border-radius:50%;background:var(--bordeaux)}\n  .tessera{background:var(--paper);border:1.5px dashed var(--cognac);border-radius:18px;padding:20px;margin-top:16px;position:relative}\n  .tessera:before,.tessera:after{content:\"\";position:absolute;width:22px;height:22px;background:var(--cream);border-radius:50%;top:50%;transform:translateY(-50%)}\n  .tessera:before{left:-13px}.tessera:after{right:-13px}\n  .pts{display:flex;align-items:baseline;gap:10px;justify-content:center}\n  .pts .n{font-family:\"Cormorant Garamond\",serif;font-size:50px;font-weight:600;color:var(--bordeaux);line-height:.9}\n  .pts .l{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--muted)}\n  .stamps{display:grid;grid-template-columns:repeat(5,1fr);gap:11px;margin:16px 6px 4px}\n  .stamp{aspect-ratio:1;border-radius:50%;border:1.5px solid var(--sand);display:flex;align-items:center;justify-content:center;font-size:18px;background:#fff;color:#cfc6ba;transition:all .35s}\n  .stamp.full{background:var(--bordeaux);border-color:var(--bordeaux);transform:rotate(-8deg)}\n  .cap{text-align:center;font-size:12px;color:var(--muted);margin-top:10px}.cap b{color:var(--bordeaux)}\n  .tierbar{height:7px;border-radius:7px;background:#f0e8dd;margin-top:14px;overflow:hidden}\n  .tierbar i{display:block;height:100%;background:linear-gradient(90deg,var(--gold),var(--bordeaux));transition:width .8s cubic-bezier(.22,.9,.3,1)}\n  .tiernote{font-size:11px;color:var(--muted);margin-top:7px;text-align:center}.tiernote b{color:var(--bordeaux)}\n\n  /* stanza / azioni */\n  .scene{text-align:center;margin-top:8px;position:relative}\n  .scene .mimi{margin:0 auto;animation:floaty 3.5s ease-in-out infinite}\n  .mname{font-family:\"Cormorant Garamond\",serif;font-size:24px;font-weight:600;margin-top:4px}\n  .mmood{font-size:12.5px;color:#7d6a5c;max-width:300px;margin:2px auto 0;min-height:34px}\n  .acts{display:flex;gap:9px;margin-top:14px}\n  .act{flex:1;border-radius:13px;padding:12px 6px;text-align:center;font-size:12px;font-weight:700;transition:all .25s;border:none}\n  .act small{display:block;font-weight:500;font-size:9.5px;opacity:.85;margin-top:2px}\n  .act.main{background:var(--bordeaux);color:#fff}\n  .act.alt{background:#fff;color:var(--bordeaux);border:1.5px solid var(--bordeaux)}\n  .act.done{background:#efe8df;color:#9a8e80}\n  .ward{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}\n  .witem{background:#fff;border-radius:14px;padding:8px;box-shadow:0 4px 14px rgba(122,46,63,.06);text-align:center;border:2px solid transparent;transition:border-color .3s}\n  .witem.worn{border-color:var(--bordeaux)}\n  .witem img{width:100%;height:74px;object-fit:cover;border-radius:10px;background:var(--peach)}\n  .witem span{font-size:9.5px;color:var(--muted);display:block;margin-top:6px;line-height:1.3}\n  .witem .w{display:inline-block;font-size:9px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:var(--bordeaux);margin-top:3px}\n  .empty{background:#fff;border:1px dashed var(--sand);border-radius:14px;padding:18px;text-align:center;font-size:12px;color:var(--muted)}\n\n  #toast{position:fixed;left:50%;bottom:26px;transform:translateX(-50%) translateY(20px);background:#2a2724;color:#fff;font-size:12.5px;padding:10px 18px;border-radius:99px;opacity:0;pointer-events:none;transition:all .3s;z-index:80;max-width:88%}\n  #toast.on{opacity:.95;transform:translateX(-50%) translateY(0)}\n\n  /* mini-gioco memory */\n  .modal{position:fixed;inset:0;background:rgba(42,39,36,.55);display:flex;align-items:center;justify-content:center;z-index:90;opacity:0;pointer-events:none;transition:opacity .25s;padding:20px}\n  .modal.on{opacity:1;pointer-events:auto}\n  .sheet{background:var(--cream);border-radius:22px;padding:22px 20px;width:100%;max-width:340px;text-align:center;box-shadow:0 20px 50px rgba(0,0,0,.3)}\n  .sheet h2{font-family:\"Cormorant Garamond\",serif;font-size:26px;font-weight:600}\n  .sheet p{font-size:12px;color:var(--muted);margin-top:4px}\n  .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:16px 0}\n  .card{aspect-ratio:3/4;border-radius:10px;background:var(--bordeaux);display:flex;align-items:center;justify-content:center;font-size:24px;cursor:pointer;color:transparent;transition:transform .25s, background .25s}\n  .card.up{background:var(--paper);color:initial;border:1.5px solid var(--sand)}\n  .card.done{background:var(--peach);color:initial;cursor:default}\n  .prizebig{font-family:\"Cormorant Garamond\",serif;font-size:44px;font-weight:700;color:var(--bordeaux);margin:6px 0}\n  .btnghost{background:none;border:none;color:var(--muted);font-size:12px;margin-top:8px;cursor:pointer;text-decoration:underline}\n\n  /* riscatto (punti -> codice sconto) */\n  .redeem{background:linear-gradient(135deg,var(--bordeaux),#5e2231);color:#fff;border-radius:18px;padding:18px 20px;margin-top:14px;box-shadow:0 10px 26px rgba(122,46,63,.22)}\n  .redeem h4{font-family:\"Cormorant Garamond\",serif;font-size:22px;font-weight:600;line-height:1.1}\n  .redeem .sub{font-size:12px;opacity:.88;margin:4px 0 12px}\n  .redeem .rbtn{background:var(--gold);color:#3c2f28;border:none;border-radius:99px;font-size:13px;font-weight:700;padding:13px 18px;cursor:pointer;width:100%;transition:transform .12s,opacity .2s}\n  .redeem .rbtn:active{transform:scale(.98)}\n  .redeem .rbtn[disabled]{background:rgba(255,255,255,.22);color:rgba(255,255,255,.7);cursor:default}\n  .codechip{display:flex;align-items:center;gap:8px;background:#fff;color:var(--bordeaux);border-radius:12px;padding:11px 12px}\n  .codechip .c{font-family:\"Cormorant Garamond\",serif;font-weight:700;font-size:19px;letter-spacing:.5px;flex:1;word-break:break-all}\n  .codechip .cp{background:var(--bordeaux);color:#fff;border:none;border-radius:8px;font-size:11px;font-weight:700;padding:8px 12px;cursor:pointer;white-space:nowrap}\n  .redeem .fine{font-size:10.5px;opacity:.82;margin-top:9px;text-align:center}\n\n  /* compleanno, bonus seconda borsa, profilo (v12) */\n  .bday{background:linear-gradient(135deg,var(--peach),var(--blush));border-radius:16px;padding:14px 16px;margin-top:14px;text-align:center}\n  .bday b{font-family:\"Cormorant Garamond\",serif;font-size:22px;font-weight:600;color:var(--bordeaux);display:block}\n  .bday span{font-size:12px;color:#7d6a5c}\n  .bonus2{font-size:11.5px;color:var(--muted);margin-top:8px;text-align:center;border-top:1px dashed var(--sand);padding-top:9px}.bonus2 b{color:var(--bordeaux)}\n  .prof{background:var(--paper);border:1px solid var(--sand);border-radius:18px;padding:18px 16px}\n  .prof .row{display:flex;gap:8px;margin-top:10px}\n  .prof label{display:block;font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:var(--cognac);margin-bottom:4px}\n  .prof select{width:100%;border:1px solid var(--sand);border-radius:10px;background:#fff;padding:10px;font-size:14px;color:var(--ink)}\n  .prof select[disabled]{background:#f4efe9;color:var(--muted)}\n  .prof .chk{display:flex;gap:9px;align-items:flex-start;margin-top:12px;font-size:12px;color:var(--muted);line-height:1.4}\n  .prof .chk input{margin-top:2px;accent-color:var(--bordeaux)}\n  .prof .sbtn{width:100%;margin-top:14px;background:var(--bordeaux);color:#fff;border:none;border-radius:99px;font-size:13px;font-weight:700;padding:12px;cursor:pointer}\n  .prof .sbtn[disabled]{opacity:.55;cursor:default}\n  .prof .sum{font-size:13px;line-height:1.7;margin-top:8px}.prof .sum b{color:var(--bordeaux)}\n  .prof .got{display:inline-block;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:var(--ok);margin-top:8px}\n  .prof .note{font-size:10.5px;color:var(--muted);margin-top:8px;line-height:1.4}\n</style>\n</head>\n<body>\n  <div class=\"logo\">amìmì</div>\n\n  <!-- stato: caricamento -->\n  <div id=\"loading\" class=\"gate\"><p>Carico il tuo profilo Premia...</p></div>\n\n  <!-- stato: login richiesto / off -->\n  <div id=\"gate\" class=\"gate hidden\">\n    <h2 id=\"gateTitle\"></h2>\n    <p id=\"gateMsg\"></p>\n    <a id=\"gateBtn\" class=\"btn\" href=\"/account\">Accedi</a>\n  </div>\n\n  <!-- profilo -->\n  <div id=\"app\" class=\"hidden\">\n    <div class=\"hello\">Ciao,<br><span id=\"cName\">amica</span></div>\n    <div><span class=\"lvl\"><span class=\"dot\"></span><span id=\"tierName\">Amica</span></span></div>\n    <div id=\"bday\" class=\"bday hidden\"></div>\n\n    <div class=\"tessera\">\n      <div class=\"pts\"><span class=\"n\" id=\"pts\">0</span><span class=\"l\">punti</span></div>\n      <div class=\"stamps\" id=\"stamps\"></div>\n      <div class=\"cap\" id=\"cap\"></div>\n      <div class=\"tierbar\"><i id=\"tierFill\" style=\"width:0%\"></i></div>\n      <div class=\"tiernote\" id=\"tierNote\"></div>\n      <div id=\"bonus2\" class=\"bonus2 hidden\"></div>\n    </div>\n\n    <div id=\"redeem\" class=\"redeem hidden\"></div>\n\n    <div id=\"profSec\" class=\"hidden\">\n      <h3 class=\"sec\">Il tuo profilo</h3>\n      <div id=\"profilo\" class=\"prof\"></div>\n    </div>\n\n    <h3 class=\"sec\">La stanza di Mimì</h3>\n    <div class=\"scene\">\n      <div class=\"mimi\" id=\"mimi\"></div>\n      <div class=\"mname\">Mimì</div>\n      <div class=\"mmood\" id=\"mood\"></div>\n    </div>\n    <div class=\"acts\">\n      <button class=\"act main tap\" id=\"btnCoccola\"></button>\n      <button class=\"act alt tap\" id=\"btnGame\">Gioca<small>1 volta al giorno</small></button>\n      <button class=\"act alt tap\" id=\"btnNanna\"></button>\n    </div>\n\n    <h3 class=\"sec\">Il guardaroba di Mimì</h3>\n    <div id=\"ward\"></div>\n  </div>\n\n  <!-- mini-gioco memory -->\n  <div class=\"modal\" id=\"gameModal\"><div class=\"sheet\">\n    <h2>Trova le coppie</h2>\n    <p>Abbina le borsine per vincere i punti di oggi.</p>\n    <div class=\"grid\" id=\"grid\"></div>\n    <button class=\"btnghost\" id=\"gameClose\">Chiudi</button>\n  </div></div>\n\n  <!-- reveal premio -->\n  <div class=\"modal\" id=\"rewardModal\"><div class=\"sheet\">\n    <h2 id=\"rewardTitle\">Complimenti!</h2>\n    <div class=\"prizebig\" id=\"rewardPrize\"></div>\n    <p id=\"rewardMsg\"></p>\n    <button class=\"btn\" id=\"rewardOk\">Continua</button>\n  </div></div>\n\n  <div id=\"toast\"></div>\n\n<script>\n(function(){\n  \"use strict\";\n\n  // === CONFIG (tiers/tessera lato client; i punti veri vengono dall'edge) ===\n  const CONFIG = {\n    stampEvery: 20, stampsForReward: 10,\n    tiers: [ {key:'amica',name:'Amica',min:0},{key:'speciale',name:'Amica Speciale',min:150},{key:'cuore',name:\"Amica del Cuore\",min:400} ],\n    materiali: ['cavallino','cocco','vernice','pelle liscia','cotone','nessuna preferenza'],   // lista chiusa, uguale al check a DB (migr 0141)\n    mesi: ['gennaio','febbraio','marzo','aprile','maggio','giugno','luglio','agosto','settembre','ottobre','novembre','dicembre'],\n  };\n  const PROXY = '/apps/premia';         // same-origin su amimi.it\n  const el = id => document.getElementById(id);\n  const esc = s => String(s ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));   // tutto cio' che entra in innerHTML passa da qui (audit T7)\n  let S = null;                          // stato reale dall'edge\n\n  // === API reale (rispecchia loyalty-proxy) ===\n  async function api(action, opts){\n    const o = opts || {};\n    const url = PROXY + '/' + action;\n    const init = { method: o.method || 'GET', headers: { 'Content-Type':'application/json' }, credentials:'include' };\n    if (o.body) init.body = JSON.stringify(o.body);\n    let r;\n    try { r = await fetch(url, init); } catch(e) { return { status:0, data:{ error:'network' } }; }   // offline o rete: gli handler mostrano \"Riprova\" (audit T30)\n    let data = {}; try { data = await r.json(); } catch(e){}\n    return { status:r.status, data };\n  }\n\n  // === tracciamento (loyalty-proxy v13, migr 0146): apertura, card viste, tap. Solo nome dell'evento e dell'elemento,\n  // in lotti (max 20, invio dopo 4 s o quando la pagina va in background), max 60 per caricamento pagina. A flag\n  // loyalty_track_enabled spento il server risponde {state:'off'} e la pagina smette di mandare. Mai bloccante, mai un toast.\n  const T = { q:[], sent:0, off:false, seen:{}, timer:null, started:false, MAX:60 };\n  function track(e, name){\n    if(T.off || T.sent + T.q.length >= T.MAX) return;\n    if(e==='view'){ if(T.seen[name]) return; T.seen[name]=1; }\n    T.q.push(name ? { e:e, el:name } : { e:e });\n    if(!T.timer) T.timer=setTimeout(flush, 4000);\n  }\n  function flush(){\n    clearTimeout(T.timer); T.timer=null;\n    if(T.off || !T.q.length) return;\n    const batch=T.q.splice(0,20); T.sent+=batch.length;\n    fetch(PROXY+'/track', { method:'POST', headers:{ 'Content-Type':'application/json' }, credentials:'include', keepalive:true, body:JSON.stringify({ events:batch }) })\n      .then(r=>r.json()).then(d=>{ if(d && d.state==='off'){ T.off=true; T.q=[]; } else if(T.q.length) flush(); }).catch(()=>{});\n  }\n  document.addEventListener('visibilitychange', ()=>{ if(document.visibilityState==='hidden') flush(); });\n  // \"vista\" = meta' della card a schermo, oppure almeno 40% dello schermo occupato (una card piu' alta di due schermi, es. un guardaroba lungo, non arriva mai al 50%)\n  const io = ('IntersectionObserver' in window) ? new IntersectionObserver(es=>{ es.forEach(x=>{ if(x.isIntersecting && x.target.dataset.trk && (x.intersectionRatio>=0.5 || x.intersectionRect.height>=window.innerHeight*0.4)) track('view', x.target.dataset.trk); }); }, { threshold:[0,0.25,0.5] }) : null;\n  function watch(id, name){ const n=el(id); if(!n || !io) return; if(name) n.dataset.trk=name; io.observe(n); }\n  function trackStart(){\n    if(T.started) return; T.started=true;\n    track('page_open');\n    watch('redeem'); watch('profSec','profilo'); watch('mimi','mimi'); watch('ward','guardaroba'); watch('bonus2','bonus2'); watch('bday','bday');\n  }\n\n  function toast(m){ const t=el('toast'); t.textContent=m; t.classList.add('on'); clearTimeout(t._t); t._t=setTimeout(()=>t.classList.remove('on'),2200); }\n  function mimiInner(){ return '<div class=\"handle\"></div><div class=\"body\"></div><div class=\"clasp\"></div><div class=\"bow\"><i></i><em></em><b></b></div><div class=\"eye l\"></div><div class=\"eye r\"></div><div class=\"cheek l\"></div><div class=\"cheek r\"></div><div class=\"mouth\"></div>'; }\n  function tierOf(p){ let t=CONFIG.tiers[0]; for(const x of CONFIG.tiers) if(p>=x.min) t=x; return t; }\n  function nextTier(p){ for(const x of CONFIG.tiers) if(p<x.min) return x; return null; }\n  function hearts(host,n){ n=n||6; for(let k=0;k<n;k++){ (function(k){ setTimeout(()=>{ const h=document.createElement('div'); h.className='heart'; h.textContent='💛'; h.style.fontSize=(14+Math.random()*8)+'px'; h.style.left=(40+Math.random()*120)+'px'; h.style.top=(30+Math.random()*60)+'px'; host.appendChild(h); setTimeout(()=>h.remove(),1400); }, k*110); })(k);} }\n  function squee(){ const m=el('mimi'); m.classList.remove('squee'); void m.offsetWidth; m.classList.add('squee'); }\n  function confetti(){ const cols=['#7a2e3f','#c9a86a','#f3d9d3','#8a6d4b','#f6e3d5']; for(let i=0;i<70;i++){ const c=document.createElement('div'); c.className='confetti'; c.style.left=Math.random()*100+'%'; c.style.top='-10px'; c.style.background=cols[i%cols.length]; c.style.animationDuration=(1.6+Math.random()*1.3)+'s'; document.body.appendChild(c); setTimeout(()=>c.remove(),3200);} }\n  function countUp(node,to){ const from=Number(node.textContent)||0; if(from===to){node.textContent=to;return;} const t0=performance.now(); (function step(t){ const k=Math.min(1,(t-t0)/650); node.textContent=Math.round(from+(to-from)*(1-Math.pow(1-k,3))); if(k<1) requestAnimationFrame(step); })(performance.now()); }\n  function reward(title,prize,msg){ el('rewardTitle').textContent=title; el('rewardPrize').textContent=prize; el('rewardMsg').textContent=msg||''; el('rewardModal').classList.add('on'); confetti(); }\n\n  // === render ===\n  function showGate(title,msg,showLogin){ el('loading').classList.add('hidden'); el('app').classList.add('hidden'); const g=el('gate'); g.classList.remove('hidden'); el('gateTitle').textContent=title; el('gateMsg').textContent=msg; el('gateBtn').classList.toggle('hidden',!showLogin); }\n\n  function render(){\n    el('loading').classList.add('hidden'); el('gate').classList.add('hidden'); el('app').classList.remove('hidden');\n    const p = S.points||0, pr = S._profile;\n    // livello: sui punti CUMULATI (server, mai scendono per un riscatto) quando il flag e' acceso; altrimenti sul saldo\n    const lifetime = !!(pr && pr.tier_lifetime_enabled);\n    const tp = lifetime ? Math.max(p, Number(pr.punti_cumulati)||0) : p;\n    const tier=tierOf(tp), nt=nextTier(tp);\n    const tierCopy = lifetime ? 'il livello segue i punti cumulati: riscattare non lo abbassa' : 'il livello segue i punti disponibili';\n    countUp(el('pts'), p);\n    el('tierName').textContent = tier.name;\n    // tessera: 10 timbri = costo del premio ATTIVO (dal server: 200 con 'tessera', 100 con 'amica12'); senza catalogo resta il CONFIG\n    const rw0 = S._rewards && Array.isArray(S._rewards.rewards) ? S._rewards.rewards[0] : null;\n    const stampEvery = (rw0 && Number(rw0.cost_points) > 0) ? Math.max(1, Math.round(Number(rw0.cost_points)/CONFIG.stampsForReward)) : CONFIG.stampEvery;\n    const timbri = Math.min(CONFIG.stampsForReward, Math.floor(p/stampEvery));\n    const sw = el('stamps'); sw.innerHTML='';\n    for(let i=1;i<=CONFIG.stampsForReward;i++){ const d=document.createElement('div'); const full=i<=timbri; d.className='stamp'+(full?' full':''); d.textContent=full?'💛':(i===CONFIG.stampsForReward?'🎁':'·'); sw.appendChild(d); }\n    el('cap').innerHTML='Un timbro ogni '+stampEvery+' punti · a '+CONFIG.stampsForReward+' timbri <b>il tuo sconto personale</b>';\n    if(nt){ const prog=Math.max(0,Math.min(1,(tp-tier.min)/(nt.min-tier.min))); el('tierFill').style.width=(prog*100)+'%'; el('tierNote').innerHTML='Ti mancano <b>'+(nt.min-tp)+' punti</b> per '+esc(nt.name)+' · '+tierCopy; }\n    else { el('tierFill').style.width='100%'; el('tierNote').innerHTML='Livello massimo: <b>'+esc(tier.name)+'</b> 💛 · '+tierCopy; }\n    renderBonus2(); renderBirthday(); renderProfile();\n    // mimi\n    const m=el('mimi'); if(!m.innerHTML.trim()) m.innerHTML=mimiInner(); m.classList.toggle('worn', !!S.worn);\n    el('mood').textContent = S.nanna ? 'Dorme nel suo sacchettino. Shhh.' : (!S.coccola_disponibile ? 'Coccolata oggi. È al settimo cielo!' : 'Oggi ti aspetta per la sua coccola.');\n    // azioni\n    const bc=el('btnCoccola');\n    if(!S.coccola_disponibile){ bc.className='act done'; bc.innerHTML='Coccolata ✓<small>torna domani</small>'; }\n    else { bc.className='act main tap'; bc.innerHTML='Coccola Mimì<small>+5 punti · 1 al giorno</small>'; }\n    const bg=el('btnGame');\n    if(!S.memory_disponibile){ bg.className='act done'; bg.innerHTML='Giocato ✓<small>torna domani</small>'; }\n    else { bg.className='act alt tap'; bg.innerHTML='Gioca<small>+5 · 1 al giorno</small>'; }\n    el('btnNanna').innerHTML = S.nanna ? 'Svegliala 💤<small>è a nanna</small>' : 'Metti a nanna<small>nel sacchettino</small>';\n    // guardaroba (borse realmente possedute)\n    const w=el('ward'), items=S.wardrobe;\n    if(items===null){ w.className='empty'; w.innerHTML='Il guardaroba non è leggibile in questo momento: riprova fra poco.'; }   // null = non leggibile (audit), diverso da \"nessun capo\"\n    else if(!items||!items.length){ w.className='empty'; w.innerHTML='Le borse che acquisti appariranno qui, pronte da far indossare a Mimì.'; }\n    else { w.className='ward'; w.innerHTML=items.map(it=>{ const worn=S.worn===it.codice; return '<div class=\"witem tap'+(worn?' worn':'')+'\" data-codice=\"'+esc(it.codice)+'\"><img src=\"'+esc(it.img||'')+'\" alt=\"\"><span>'+esc(it.titolo||it.codice)+'</span><span class=\"w\">'+(worn?'indossata':'indossa')+'</span></div>'; }).join(''); }\n    renderRedeem();\n  }\n\n  // === riscatto (punti -> codice sconto). Catalogo/riscatti dall'edge (azioni rewards/redeem). ===\n  function renderRedeem(){\n    const box=el('redeem'); const rd=S && S._rewards;\n    if(!rd || !Array.isArray(rd.rewards) || !rd.rewards.length){ box.classList.add('hidden'); return; }\n    const rw=rd.rewards[0];                                   // primo premio attivo ('tessera')\n    const p=S.points||0, reds=rd.redemptions||[];\n    const pending=reds.find(x=>x.status==='pending');\n    const last=reds.find(x=>x.status==='fulfilled' && x.discount_code);   // il piu' recente (lista gia' desc)\n    box.classList.remove('hidden');\n    box.dataset.trk = pending ? 'redeem_pending' : (p>=rw.cost_points ? 'redeem_ready' : 'redeem_locked');   // letto dal tracciamento quando la card entra in vista\n    let h='<h4>'+esc(rw.label)+'</h4>';\n    // azione: il riscatto e' RIPETIBILE ogni volta che la tessera si riempie\n    if(pending){\n      h+='<div class=\"sub\">Riscatto ricevuto. Il tuo codice sta arrivando, ti avvisiamo.</div>';\n    } else if(p>=rw.cost_points){\n      h+='<div class=\"sub\">Hai '+p+' punti: puoi riscattare il tuo sconto.</div>'\n        +'<button class=\"rbtn tap\" id=\"rbtn\" data-reward=\"'+rw.key+'\">Riscatta '+(rw.value?rw.value+'%':'sconto')+' · '+rw.cost_points+' punti</button>'\n        +'<div class=\"fine\">Scala '+rw.cost_points+' punti · non cumulabile</div>';\n    } else {\n      h+='<div class=\"sub\">Il tuo sconto personale, a tessera piena.</div>'\n        +'<button class=\"rbtn\" disabled>Ti mancano '+(rw.cost_points-p)+' punti</button>';\n    }\n    // ultimo codice ottenuto: resta sempre a portata di mano\n    if(last){\n      h+='<div class=\"fine\" style=\"margin-top:12px;text-align:left\">Il tuo ultimo codice</div>'\n        +'<div class=\"codechip\" style=\"margin-top:6px\"><span class=\"c\">'+esc(last.discount_code)+'</span><button class=\"cp\" data-code=\"'+esc(last.discount_code)+'\">Copia</button></div>'\n        +'<div class=\"fine\">'+(rw.value?rw.value+'% · ':'')+'non cumulabile · uso singolo</div>';\n    }\n    box.innerHTML=h;\n  }\n\n  // === compleanno, seconda borsa, profilo (v12: azione profile; a flag OFF tutto resta nascosto) ===\n  function itDate(iso){ const m=/^(\\d{4})-(\\d{2})-(\\d{2})/.exec(String(iso||'')); return m ? (m[3]+'/'+m[2]+'/'+m[1]) : ''; }\n  function renderBirthday(){\n    const b=el('bday'), pr=S._profile;\n    if(!pr || !pr.profile_enabled || !pr.birthday_today){ b.classList.add('hidden'); return; }\n    b.classList.remove('hidden');\n    b.innerHTML='<b>Buon compleanno! 🎀</b><span>Mimì ti fa tanti auguri'+(pr.birthday_awarded ? ' · <b style=\"display:inline;font-size:13px\">+20 punti di regalo</b> sul tuo saldo' : '')+'</span>';\n  }\n  function renderBonus2(){\n    const b=el('bonus2'), pr=S._profile, bs=pr && pr.bonus_second_enabled ? pr.bonus_second : null;\n    if(!bs){ b.classList.add('hidden'); return; }\n    if(bs.awarded){ b.classList.remove('hidden'); b.innerHTML='Bonus seconda borsa ricevuto: <b>+50 punti</b> 💛'; return; }\n    if(bs.ordini===1 && bs.deadline){\n      const gg=Math.max(0, Number(bs.days_left)||0);   // giorni calcolati dal server in Europe/Rome, mai dal fuso del browser\n      b.classList.remove('hidden');\n      b.innerHTML='Seconda borsa entro il <b>'+esc(itDate(bs.deadline))+'</b>: <b>+50 punti</b>'+(gg>0 ? ' · '+gg+(gg===1?' giorno':' giorni') : ' · oggi');\n      return;\n    }\n    b.classList.add('hidden');\n  }\n  function renderProfile(){\n    const sec=el('profSec'), box=el('profilo'), pr=S._profile;\n    if(!pr || !pr.profile_enabled){ sec.classList.add('hidden'); return; }\n    sec.classList.remove('hidden');\n    const P=pr.profile||{};\n    if(P.complete){\n      box.innerHTML='<div class=\"sum\">Compleanno: <b>'+esc(P.birth_day)+' '+esc(CONFIG.mesi[(P.birth_month||1)-1]||'')+'</b><br>Materiale preferito: <b>'+esc(P.materiale_preferito||'')+'</b><br>Regalo di compleanno: <b>'+(P.consenso_compleanno?'sì':'no')+'</b></div>'\n        +'<span class=\"got\">+10 punti ricevuti ✓</span>'\n        +'<div class=\"chk\"><input type=\"checkbox\" id=\"pConsenso\" '+(P.consenso_compleanno?'checked':'')+'><label for=\"pConsenso\" style=\"text-transform:none;letter-spacing:0;font-size:12px;color:var(--muted)\">Voglio il regalo di compleanno. Usiamo solo giorno e mese per farti un regalo di compleanno. Niente anno.</label></div>'\n        +'<button class=\"sbtn tap\" id=\"pSave\">Aggiorna</button>'\n        +'<div class=\"note\">La data di compleanno non si modifica da qui: per una correzione scrivi all\\'assistenza.</div>';\n      return;\n    }\n    const locked=!!P.birth_locked;\n    let days=''; for(let d=1;d<=31;d++) days+='<option value=\"'+d+'\"'+(P.birth_day===d?' selected':'')+'>'+d+'</option>';\n    let months=''; CONFIG.mesi.forEach((m,i)=>{ months+='<option value=\"'+(i+1)+'\"'+(P.birth_month===i+1?' selected':'')+'>'+esc(m)+'</option>'; });\n    let mats=''; CONFIG.materiali.forEach(m=>{ mats+='<option value=\"'+esc(m)+'\"'+(P.materiale_preferito===m?' selected':'')+'>'+esc(m)+'</option>'; });\n    box.innerHTML='<div class=\"note\" style=\"margin-top:0\">Completa il profilo e ricevi <b>+10 punti</b>. Il giorno del tuo compleanno Mimì ti regala <b>+20 punti</b>.</div>'\n      +'<div class=\"row\"><div style=\"flex:1\"><label>Giorno</label><select id=\"pDay\"'+(locked?' disabled':'')+'><option value=\"\">-</option>'+days+'</select></div>'\n      +'<div style=\"flex:2\"><label>Mese</label><select id=\"pMonth\"'+(locked?' disabled':'')+'><option value=\"\">-</option>'+months+'</select></div></div>'\n      +'<div class=\"row\"><div style=\"flex:1\"><label>Materiale preferito</label><select id=\"pMat\"><option value=\"\">-</option>'+mats+'</select></div></div>'\n      +'<div class=\"chk\"><input type=\"checkbox\" id=\"pConsenso\" '+(P.consenso_compleanno?'checked':'')+'><label for=\"pConsenso\" style=\"text-transform:none;letter-spacing:0;font-size:12px;color:var(--muted)\">Voglio il regalo di compleanno. Usiamo solo giorno e mese per farti un regalo di compleanno. Niente anno.</label></div>'\n      +'<button class=\"sbtn tap\" id=\"pSave\">Salva il profilo</button>'\n      +(locked ? '<div class=\"note\">La data di compleanno è già salvata e non si modifica da qui.</div>' : '<div class=\"note\">Il regalo di compleanno arriva se il profilo è salvato almeno 30 giorni prima.</div>');\n  }\n  el('profilo').addEventListener('click', async e=>{\n    const btn=e.target.closest('#pSave'); if(!btn||!S) return;\n    track('tap','profile_save');\n    const day=el('pDay'), month=el('pMonth'), mat=el('pMat'), cons=el('pConsenso');\n    const body={ consenso: !!(cons && cons.checked) };\n    if(day && !day.disabled && day.value) body.birth_day=Number(day.value);\n    if(month && !month.disabled && month.value) body.birth_month=Number(month.value);\n    if(mat && mat.value) body.materiale=mat.value;\n    if(day && !day.disabled && ((body.birth_day && !body.birth_month) || (!body.birth_day && body.birth_month))){ toast('Scegli giorno e mese'); return; }\n    btn.disabled=true; btn.textContent='Salvo...';\n    const { data } = await api('profile_save',{method:'POST',body});\n    if(data && data.ok){\n      await refresh(false);\n      if(data.awarded) reward('Profilo completo!', '+10', 'punti aggiunti al tuo saldo 💛');\n      else toast(data.birthday_locked ? 'Profilo aggiornato (la data resta quella salvata)' : 'Profilo aggiornato 💛');\n    } else if(data && data.error==='bad_date'){ toast('Questa data non esiste'); btn.disabled=false; btn.textContent='Salva il profilo'; }\n    else { toast('Riprova fra poco'); btn.disabled=false; btn.textContent='Riprova'; }\n  });\n\n  async function refresh(animate){\n    const [st, rw, pf] = await Promise.all([api('state'), api('rewards'), api('profile')]);   // rewards/profile: OFF finche' i flag sono spenti\n    const { status, data } = st;\n    if (data.state==='login_required') return showGate('Il tuo profilo Premia','Accedi con il tuo account Amimì per vedere i tuoi punti e prenderti cura di Mimì.', true);\n    if (data.state==='needs_secret' || data.state==='off') return showGate('Premia sta arrivando','Il programma fedeltà parte a breve. Torna presto!', false);\n    if (status===503 || data.error) return showGate('Un attimo...','Non riesco a leggere il profilo in questo momento. Riprova fra poco.', false);\n    S = data;\n    S._rewards = (rw && rw.data && Array.isArray(rw.data.rewards)) ? rw.data : null;\n    S._profile = (pf && pf.status===200 && pf.data && !pf.data.error && typeof pf.data.profile_enabled==='boolean') ? pf.data : null;   // non leggibile = come a flag OFF, mai una card finta\n    render();\n    trackStart();\n  }\n\n  // === azioni ===\n  el('btnCoccola').addEventListener('click', async ()=>{\n    if(!S || !S.coccola_disponibile) return;\n    track('tap','coccola');\n    const { data } = await api('coccola');\n    if(data.done_today){ toast('Mimì è già stata coccolata oggi 💛'); return; }\n    if(data.error){ toast('Riprova fra poco'); return; }\n    S.points=data.points; S.coccola_disponibile=false; squee(); hearts(el('scene'),6); render(); toast('+'+(data.added||5)+' punti · coccola di oggi ✓');\n  });\n\n  el('btnNanna').addEventListener('click', async ()=>{\n    if(!S) return; track('tap','nanna'); const { data } = await api('nanna',{method:'POST',body:{value:!S.nanna}});\n    if(typeof data.nanna==='boolean'){ S.nanna=data.nanna; render(); toast(S.nanna?'Mimì è a nanna 💤':'Buongiorno!'); }\n  });\n\n  el('ward').addEventListener('click', async e=>{\n    const it=e.target.closest('.witem'); if(!it||!S) return;\n    track('tap','wear');\n    const { status, data } = await api('wear',{method:'POST',body:{codice:it.dataset.codice}});\n    if(status===409||data.error==='not_owned'){ toast('Puoi far indossare a Mimì solo le tue borse'); return; }\n    if(data.worn){ S.worn=data.worn; squee(); hearts(el('scene'),3); render(); }\n  });\n\n  // riscatto: copia codice oppure riscatta (bottone disabilitato subito = anti doppio-click; idemp lato server)\n  el('redeem').addEventListener('click', async e=>{\n    const cp=e.target.closest('.cp');\n    if(cp){ track('tap','copy_code'); const code=cp.dataset.code||''; try{ await navigator.clipboard.writeText(code); toast('Codice copiato 💛'); }catch(_){ toast('Codice: '+code); } return; }\n    const btn=e.target.closest('#rbtn'); if(!btn||!S) return;\n    track('tap','redeem');\n    const rw=(S._rewards&&S._rewards.rewards&&S._rewards.rewards[0])||{};\n    const pct=rw.value?('-'+rw.value+'%'):'Sconto';\n    btn.disabled=true; btn.textContent='Riscatto...';\n    const idemp='r-'+Date.now()+'-'+Math.random().toString(36).slice(2,10);\n    const { data } = await api('redeem',{method:'POST',body:{reward:btn.dataset.reward, idemp}});\n    if(data && data.ok){\n      await refresh(false);\n      if(data.code) reward('Sconto sbloccato!', pct, 'Codice '+data.code+' · non cumulabile, usalo al checkout');\n      else toast('Riscatto ricevuto, codice in arrivo 💛');\n    } else if(data && data.reason==='insufficient'){ toast('Punti non sufficienti'); renderRedeem(); }\n    else { toast('Riprova fra poco'); btn.disabled=false; btn.textContent='Riprova'; }\n  });\n\n  // === mini-gioco memory: vinci -> chiama memory_win (premio deciso dall'edge) ===\n  const EMO=['👜','👛','🎀','👜','👛','🎀'];\n  el('btnGame').addEventListener('click', ()=>{ if(!S||!S.memory_disponibile){ toast('Torna domani per un nuovo gioco 🎀'); return; } track('tap','gioco'); startGame(); });\n  el('gameClose').addEventListener('click', ()=>el('gameModal').classList.remove('on'));\n  el('rewardOk').addEventListener('click', ()=>el('rewardModal').classList.remove('on'));\n  function startGame(){\n    const grid=el('grid'); grid.innerHTML='';\n    const cards=EMO.slice().sort(()=>Math.random()-0.5);\n    let up=[], matched=0, lock=false;\n    cards.forEach((emo,i)=>{ const c=document.createElement('div'); c.className='card'; c.dataset.emo=emo; c.textContent=emo;\n      c.addEventListener('click',()=>{\n        if(lock||c.classList.contains('up')||c.classList.contains('done'))return;\n        c.classList.add('up'); up.push(c);\n        if(up.length===2){ lock=true;\n          if(up[0].dataset.emo===up[1].dataset.emo){ up.forEach(x=>x.classList.add('done')); matched++; up=[]; lock=false;\n            if(matched===3) setTimeout(winGame,350);\n          } else setTimeout(()=>{ up.forEach(x=>x.classList.remove('up')); up=[]; lock=false; },700);\n        }\n      });\n      grid.appendChild(c);\n    });\n    el('gameModal').classList.add('on');\n  }\n  async function winGame(){\n    el('gameModal').classList.remove('on');\n    const { data } = await api('memory_win');\n    if(data.done_today){ toast('Hai già giocato oggi'); return; }\n    if(data.error){ toast('Riprova fra poco'); return; }\n    S.points=data.points; S.memory_disponibile=false; render();\n    reward('Hai vinto!', '+'+(data.added||5), 'punti aggiunti al tuo saldo 💛');\n  }\n\n  refresh(false);\n})();\n</script>\n</body>\n</html>\n{% endraw %}";
const cors = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "content-type", "Access-Control-Allow-Methods": "GET, OPTIONS" };
Deno.serve((req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: cors });
  const v2 = new URL(req.url).searchParams.get("v") === "2";
  return new Response(v2 ? BODY : BODY_V1, { headers: { ...cors, "Content-Type": "application/liquid; charset=utf-8" } });
});
